// Fire-and-forget log entry to Google Sheets via Apps Script.
// Never blocks or fails the actual download — logging issues shouldn't
// stop someone from getting their file.
function logLessonEntry({ mode, lessonCode, timestamp, filename }) {
  if (!CONFIG.LESSON_LOG_SCRIPT_URL || CONFIG.LESSON_LOG_SCRIPT_URL.includes("PASTE_YOUR")) return;
  fetch(CONFIG.LESSON_LOG_SCRIPT_URL, {
    method: "POST",
    // text/plain avoids a CORS preflight, which Apps Script Web Apps don't handle
    headers: { "Content-Type": "text/plain;charset=utf-8" },
    body: JSON.stringify({ mode, lessonCode, timestamp, filename, loggedAt: new Date().toISOString() }),
  }).catch(() => {});
}

// Fires for every account, on every successful generation, across all
// features. Reuses the same Apps Script endpoint — routed to its own
// "Usage" sheet based on this payload's shape (has "email"/"characters",
// not "lessonCode").
function logUsageEntry({ email, mode, characters, seconds }) {
  if (!CONFIG.LESSON_LOG_SCRIPT_URL || CONFIG.LESSON_LOG_SCRIPT_URL.includes("PASTE_YOUR")) return;
  fetch(CONFIG.LESSON_LOG_SCRIPT_URL, {
    method: "POST",
    headers: { "Content-Type": "text/plain;charset=utf-8" },
    body: JSON.stringify({ email, mode, characters: characters || 0, seconds: seconds || 0, loggedAt: new Date().toISOString() }),
  }).catch(() => {});
}

// ─ Shared voice library — saved voices are visible to every user, not tied
// to an account. Reuses the same Apps Script endpoint as usage/lesson logging.
// Writes a voice to the shared library sheet. Throws on any definite failure so
// callers can tell the user and roll back, instead of leaving a voice that
// exists on ElevenLabs but never appears in the list.
async function saveVoiceToLibrary({ voiceId, name, addedBy, language, category }) {
  if (!CONFIG.LESSON_LOG_SCRIPT_URL || CONFIG.LESSON_LOG_SCRIPT_URL.includes("PASTE_YOUR")) {
    throw new Error("The voice library isn't configured.");
  }
  let res;
  try {
    res = await fetch(CONFIG.LESSON_LOG_SCRIPT_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify({ action: "save_voice", voiceId, name, addedBy, language, category, loggedAt: new Date().toISOString() }),
    });
  } catch {
    throw new Error("Couldn't reach the voice library.");
  }
  if (!res.ok) throw new Error("The voice library returned an error.");
  // The script answers {"status":"ok"} on success. Anything else readable
  // (an error object, or Google's HTML error page) means the row wasn't written.
  let data = null;
  try { data = JSON.parse(await res.text()); } catch { /* non-JSON = error page */ }
  if (!data || data.status !== "ok") throw new Error("The voice library didn't confirm the save.");
}

