// ─ Voice library constants — categories/languages available when saving,
// and a deterministic avatar (initials + color) generated from a name so
// no image upload is needed.
const VOICE_CATEGORIES = ["Conversational", "Narration", "Characters", "Social Media", "Educational"];
const VOICE_LANGUAGES = ["English", "Yoruba", "Igbo", "Hausa", "Swahili"];
const AVATAR_COLORS = ["#137a44", "#B45309", "#7C3AED", "#0E7490", "#BE185D", "#4338CA", "#B91C1C", "#047857"];

function voiceAvatar(name) {
  const str = name || "?";
  let hash = 0;
  for (let i = 0; i < str.length; i++) hash = str.charCodeAt(i) + ((hash << 5) - hash);
  const color = AVATAR_COLORS[Math.abs(hash) % AVATAR_COLORS.length];
  const initials = str.trim().split(/\s+/).slice(0, 2).map(w => w[0]?.toUpperCase() || "").join("") || "?";
  return { color, initials };
}

