// ─ Safe JSON parser — Vercel can return plain-text errors (e.g. "Request
//   Entity Too Large") that break res.json(). This gives a clear message. ──
async function safeJson(res) {
  const text = await res.text();
  try {
    return JSON.parse(text);
  } catch {
    if (text.toLowerCase().includes("entity too large") || text.toLowerCase().includes("too large")) {
      throw new Error("This file is too large to process. Try a shorter or compressed recording.");
    }
    throw new Error(text || "Unexpected server response");
  }
}

// ─ ElevenLabs helpers ─────────────────────────────────────────────────────
async function cloneVoice(audioFile, name) {
  const form = new FormData();
  form.append("name", name);
  const filename = audioFile.name || (audioFile.type?.includes("mp4") ? "sample.mp4" : "sample.webm");
  form.append("files", audioFile, filename);
  const res = await fetch("https://api.elevenlabs.io/v1/voices/add", {
    method: "POST",
    headers: { "xi-api-key": CONFIG.ELEVENLABS_API_KEY },
    body: form,
  });
  if (!res.ok) {
    const err = await safeJson(res).catch(() => ({}));
    throw new Error(err.detail?.message || err.message || "Voice cloning failed");
  }
  const data = await safeJson(res);
  return data.voice_id;
}

async function deleteVoice(voiceId) {
  await fetch(`https://api.elevenlabs.io/v1/voices/${voiceId}`, {
    method: "DELETE",
    headers: { "xi-api-key": CONFIG.ELEVENLABS_API_KEY },
  });
}

// Clone a fresh voice from the stored sample, run fn with the voice_id,
// then delete the clone regardless of success or failure.
async function withClonedVoice(sampleFile, fn) {
  // A string means this is already a real ElevenLabs voice ID — a saved
  // library voice, not a fresh sample to clone. Use it directly, and never
  // delete it, since library voices are meant to persist.
  if (typeof sampleFile === "string") {
    return await fn(sampleFile);
  }
  const voiceId = await cloneVoice(sampleFile, `accentuate_${Date.now()}`);
  try {
    return await fn(voiceId);
  } finally {
    deleteVoice(voiceId).catch(() => {});
  }
}

// Remove background noise from an audio sample before cloning
async function isolateVoice(audioFile) {
  const form = new FormData();
  const filename = audioFile.name || (audioFile.type?.includes("mp4") ? "sample.mp4" : "sample.webm");
  form.append("audio", audioFile, filename);
  const res = await fetch("https://api.elevenlabs.io/v1/audio-isolation", {
    method: "POST",
    headers: { "xi-api-key": CONFIG.ELEVENLABS_API_KEY },
    body: form,
  });
  if (!res.ok) throw new Error("Audio cleanup failed");
  const blob = await res.blob();
  return new File([blob], filename, { type: blob.type || "audio/mpeg" });
}

// Get the duration of an audio file in seconds
async function getAudioDuration(file) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const audio = new Audio();

    const finish = (duration) => {
      URL.revokeObjectURL(url);
      resolve(duration);
    };

    audio.addEventListener("loadedmetadata", () => {
      // Chrome (and others) often can't read a real duration from WebM
      // blobs straight out of MediaRecorder — it comes back as NaN or
      // Infinity until the browser is forced to actually scan the file.
      if (!isFinite(audio.duration)) {
        audio.currentTime = 1e101;
        audio.addEventListener("timeupdate", function onTimeUpdate() {
          audio.removeEventListener("timeupdate", onTimeUpdate);
          audio.currentTime = 0;
          finish(isFinite(audio.duration) ? audio.duration : 0);
        });
      } else {
        finish(audio.duration);
      }
    });
    audio.addEventListener("error", () => {
      URL.revokeObjectURL(url);
      reject(new Error("Could not read audio duration"));
    });
    audio.src = url;
  });
}

// Transcribe an uploaded audio file to text — used by Convert Audio
async function transcribeAudio(audioFile) {
  const form = new FormData();
  const filename = audioFile.name || "audio.mp3";
  form.append("file", audioFile, filename);
  // scribe_v1 is deprecated by ElevenLabs on July 9, 2026 — scribe_v2 is the
  // supported replacement, and also gives us word-level timestamps, which
  // the pacing-matching pipeline below needs.
  form.append("model_id", "scribe_v2");
  form.append("timestamps_granularity", "word");
  const res = await fetch("https://api.elevenlabs.io/v1/speech-to-text", {
    method: "POST",
    headers: { "xi-api-key": CONFIG.ELEVENLABS_API_KEY },
    body: form,
  });
  if (!res.ok) {
    const err = await safeJson(res).catch(() => ({}));
    throw new Error(err.detail?.message || err.message || "Transcription failed");
  }
  const data = await safeJson(res);
  if (!data.text || !data.text.trim()) throw new Error("Couldn't detect any speech in that file");
  // data.words includes "word", "spacing", and "audio_event" entries with
  // start/end times; we only need the actual words for sentence/timing work.
  const words = (data.words || []).filter(w => w.type === "word" && w.text && w.text.trim());
  return { text: data.text, words };
}

// Common English abbreviations whose trailing "." doesn't end a sentence —
// mirrors the set normalizeTextForTTS() expands, so sentence-boundary
// detection at the word-timestamp level doesn't split on them.
const ABBREVIATIONS = new Set(["mr", "mrs", "ms", "dr", "prof", "jr", "sr", "vs", "etc", "e.g", "i.e", "a.m", "p.m", "no", "fig"]);

// Group STT word timestamps into sentence-level segments, each carrying the
// original clip's start/end time so generated audio can be paced to match.
function splitWordsIntoSentences(words) {
  const sentences = [];
  let current = [];

  const endsSentence = (word) => {
    const w = word.trim();
    if (w.endsWith("?")) return true;
    if (w.endsWith(".")) {
      const stripped = w.replace(/\.+$/, "").toLowerCase();
      if (ABBREVIATIONS.has(stripped)) return false;
      return true;
    }
    return false;
  };

  for (const word of words) {
    current.push(word);
    if (endsSentence(word.text)) {
      sentences.push(current);
      current = [];
    }
  }
  if (current.length) sentences.push(current);

  return sentences.map((group, i) => ({
    text: group.map(w => w.text).join(" "),
    start: group[0].start,
    end: group[group.length - 1].end,
  }));
}

// Generate TTS for a sentence, then measure and correct its speed so the
// output duration matches the original segment's duration as closely as
// ElevenLabs' speed parameter allows (0.7x-1.2x).
async function generateSentencePaced(text, anchorVoiceId, targetDuration) {
  let speed = 1.0;
  let blob = await generateChunkAudio(text, anchorVoiceId, speed);
  let duration = await getAudioDuration(new File([blob], "chunk.mp3", { type: blob.type || "audio/mpeg" }));

  if (targetDuration > 0.05) {
    const ratio = duration / targetDuration;
    if (Math.abs(ratio - 1) > 0.08) {
      const correctedSpeed = Math.min(1.2, Math.max(0.7, speed * ratio));
      if (Math.abs(correctedSpeed - speed) > 0.02) {
        blob = await generateChunkAudio(text, anchorVoiceId, correctedSpeed);
      }
    }
  }
  return blob;
}

const MAX_SENTENCE_GAP_SECONDS = 2.5;

// Decode audio blobs, insert silence matching the original's inter-sentence
// gaps, and re-encode — same WAV pipeline as concatenateAudioBlobs, extended
// to preserve pacing between segments rather than gluing them back to back.
async function concatenateWithGaps(segments) {
  const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  const decoded = await Promise.all(
    segments.map(async s => audioCtx.decodeAudioData((await s.blob.arrayBuffer()).slice(0)))
  );

  const numChannels = decoded[0].numberOfChannels;
  const sampleRate = decoded[0].sampleRate;

  let totalLength = 0;
  const gapSamples = segments.map(s => Math.round(Math.min(MAX_SENTENCE_GAP_SECONDS, Math.max(0, s.gapAfter || 0)) * sampleRate));
  decoded.forEach((buf, i) => { totalLength += buf.length + (i < decoded.length - 1 ? gapSamples[i] : 0); });

  const output = audioCtx.createBuffer(numChannels, totalLength, sampleRate);
  let offset = 0;
  decoded.forEach((buf, i) => {
    for (let ch = 0; ch < numChannels; ch++) {
      output.getChannelData(ch).set(buf.getChannelData(ch), offset);
    }
    offset += buf.length;
    if (i < decoded.length - 1) offset += gapSamples[i]; // silence gap stays zero-filled
  });

  return audioBufferToWavBlob(output);
}


// ─ ElevenLabs chunked TTS functions ───────────────────────────────────────

// Split text into chunks under maxLen, breaking at sentence boundaries
function chunkScript(text, maxLen = 2000) {
  // Split ONLY on . or ? followed by whitespace — NOT on !
  // This prevents false splits on text like "Kano@2024!6k"
  // Exclamation marks are rare sentence-enders in educational/business scripts
  const parts = text.split(/(?<=[.?])\s+/);
  const sentences = parts.map(s => s.trim()).filter(Boolean);
  const chunks = [];
  let current = "";

  for (const sentence of sentences) {
    if ((current + " " + sentence).length > maxLen && current.length > 0) {
      chunks.push(current.trim());
      current = sentence;
    } else {
      current = current ? current + " " + sentence : sentence;
    }
  }
  if (current.trim()) chunks.push(current.trim());
  return chunks.length > 0 ? chunks : [text];
}

// Minimal pre-processing before sending to ElevenLabs TTS.
// Only fixes things that break OUR pipeline (chunker, newlines).
// Everything else is left for ElevenLabs' own normalizer (apply_text_normalization: "on").
function normalizeTextForTTS(text) {
  return text
    // Normalize newlines to spaces — prevents model from skipping paragraphs
    .replace(/\r\n/g, " ")
    .replace(/\n/g, " ")
    .replace(/\r/g, " ")
    // Abbreviations with internal periods — prevents chunker from splitting on them
    .replace(/\ba\.m\.\s/gi, "AM ")
    .replace(/\bp\.m\.\s/gi, "PM ")
    .replace(/\ba\.m\.,/gi, "AM,")
    .replace(/\bp\.m\.,/gi, "PM,")
    .replace(/\ba\.m\./gi, "AM ")
    .replace(/\bp\.m\./gi, "PM ")
    .replace(/\be\.g\.\s/gi, "for example ")
    .replace(/\bi\.e\.\s/gi, "that is ")
    .replace(/\betc\.\s/gi, "etcetera ")
    .replace(/\bvs\.\s/gi, "versus ")
    .replace(/\bdr\.\s/gi, "Doctor ")
    .replace(/\bprof\.\s/gi, "Professor ")
    .replace(/\bmr\.\s/gi, "Mister ")
    .replace(/\bmrs\.\s/gi, "Missus ")
    .replace(/\bms\.\s/gi, "Ms ")
    .replace(/\bjr\.\s/gi, "Junior ")
    .replace(/\bsr\.\s/gi, "Senior ")
    .replace(/\bno\.\s/gi, "number ")
    .replace(/\bfig\.\s/gi, "figure ")
    // Clean up double spaces
    .replace(/\s{2,}/g, " ")
    .trim();
}

// Generate TTS for a single chunk via anchor voice
// Text should already be normalized before calling this
async function generateChunkAudio(chunkText, anchorVoiceId, speed = 1.0, seed = null) {
  const res = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${anchorVoiceId}`, {
    method: "POST",
    headers: {
      "xi-api-key": CONFIG.ELEVENLABS_API_KEY,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      text: chunkText,
      model_id: "eleven_v3",
      language_code: "en",
      apply_text_normalization: "on",
      // Request stitching (previous_request_ids) isn't supported on eleven_v3,
      // so a shared seed across every chunk of one generation is the
      // available lever for keeping delivery consistent between them.
      // Stability raised from 0.5 → 0.7 for the same reason — less
      // per-call variation, at some cost to expressiveness.
      voice_settings: { stability: 0.7, similarity_boost: 0.75, speed },
      ...(seed !== null ? { seed } : {}),
    }),
  });
  if (!res.ok) {
    const err = await safeJson(res).catch(() => ({}));
    throw new Error(err.detail?.message || err.message || "TTS generation failed");
  }
  return await res.blob();
}

// Concatenate multiple audio blobs into one
async function concatenateAudioBlobs(blobs) {
  if (blobs.length === 1) return blobs[0];

  const buffers = await Promise.all(blobs.map(b => b.arrayBuffer()));
  const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

  const decoded = await Promise.all(
    buffers.map(buf => audioCtx.decodeAudioData(buf.slice(0)))
  );

  const numChannels = decoded[0].numberOfChannels;
  const sampleRate = decoded[0].sampleRate;

  // 400ms of silence between chunks — without this, chunk boundaries (which
  // land on sentence breaks) sound like an unnaturally rushed continuation,
  // since two separate TTS calls get glued with zero breathing room.
  const gapSamples = Math.round(0.4 * sampleRate);
  const totalLength = decoded.reduce((sum, d, i) => sum + d.length + (i < decoded.length - 1 ? gapSamples : 0), 0);

  const output = audioCtx.createBuffer(numChannels, totalLength, sampleRate);

  let offset = 0;
  decoded.forEach((buf, i) => {
    for (let ch = 0; ch < numChannels; ch++) {
      output.getChannelData(ch).set(buf.getChannelData(ch), offset);
    }
    offset += buf.length;
    if (i < decoded.length - 1) offset += gapSamples; // silence gap stays zero-filled
  });

  // Encode back to WAV blob
  return audioBufferToWavBlob(output);
}

// Convert AudioBuffer to WAV Blob
function audioBufferToWavBlob(buffer) {
  const numChannels = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;
  const length = buffer.length * numChannels * 2 + 44;
  const arrBuf = new ArrayBuffer(length);
  const view = new DataView(arrBuf);

  const writeString = (offset, str) => {
    for (let i = 0; i < str.length; i++) view.setUint8(offset + i, str.charCodeAt(i));
  };

  writeString(0, "RIFF");
  view.setUint32(4, length - 8, true);
  writeString(8, "WAVE");
  writeString(12, "fmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * numChannels * 2, true);
  view.setUint16(32, numChannels * 2, true);
  view.setUint16(34, 16, true);
  writeString(36, "data");
  view.setUint32(40, length - 44, true);

  let offset = 44;
  for (let i = 0; i < buffer.length; i++) {
    for (let ch = 0; ch < numChannels; ch++) {
      let sample = buffer.getChannelData(ch)[i];
      sample = Math.max(-1, Math.min(1, sample));
      view.setInt16(offset, sample < 0 ? sample * 0x8000 : sample * 0x7FFF, true);
      offset += 2;
    }
  }

  return new Blob([arrBuf], { type: "audio/wav" });
}

async function voiceChangerFromBlob(audioBlob, targetVoiceId) {
  const form = new FormData();
  form.append("audio", audioBlob, "anchor_output.mp3");
  form.append("model_id", "eleven_multilingual_sts_v2");
  form.append("voice_settings", JSON.stringify({ stability: 0.5, similarity_boost: 0.85 }));
  const res = await fetch(
    `https://api.elevenlabs.io/v1/speech-to-speech/${targetVoiceId}`,
    {
      method: "POST",
      headers: { "xi-api-key": CONFIG.ELEVENLABS_API_KEY },
      body: form,
    }
  );
  if (!res.ok) {
    const err = await safeJson(res).catch(() => ({}));
    const detail = err.detail?.message || err.message || "";
    throw new Error(detail || `Voice conversion failed (${res.status}). This may be a rate limit — try a shorter script or wait a moment.`);
  }
  return await res.blob();
}

async function uploadToCloudinary(blob, filename) {
  const form = new FormData();
  form.append("file", blob, filename);
  form.append("upload_preset", "c9wnfmg1");
  form.append("resource_type", "video"); // Cloudinary uses "video" for audio files
  const res = await fetch("https://api.cloudinary.com/v1_1/dpfcldjam/video/upload", {
    method: "POST",
    body: form,
  });
  const data = await res.json();
  if (!data.secure_url) throw new Error("Cloudinary upload failed");
  return data.secure_url;
}

