// ─ Waveform (audio-player scrubber visual — JS driven, unchanged logic) ───
function Waveform({ active, bars = 40, height = 48, color }) {
  const [t, setT] = useState(0);
  useEffect(() => {
    if (!active) return;
    const id = setInterval(() => setT(n => n + 1), 60);
    return () => clearInterval(id);
  }, [active]);
  const activeColor = color || `linear-gradient(to top, ${C.green}, #4ADE80)`;
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 3, height, overflow: "hidden" }}>
      {Array.from({ length: bars }).map((_, i) => {
        const wave = active
          ? Math.abs(Math.sin(t * 0.18 + i * 0.45)) * (height * 0.75) + height * 0.12
          : height * 0.08;
        return (
          <div key={i} style={{
            width: 3, borderRadius: 3,
            background: active ? activeColor : C.border,
            height: wave,
            transition: active ? "height 0.06s ease" : "height 0.5s ease",
            opacity: active ? 1 : 0.6,
          }} />
        );
      })}
    </div>
  );
}

