// ─ Ripple panel — wraps the green gradient hero panel and spawns soft
//   ripples on pointer movement, matching the Claude Design export. ──────
function RipplePanel({ children, style, className }) {
  const [ripples, setRipples] = useState([]);
  const lastRef = useRef({ t: 0, pt: null });
  const ridRef = useRef(0);

  const onMove = (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left, y = e.clientY - rect.top;
    const now = Date.now();
    if (now - lastRef.current.t < 55) return;
    if (lastRef.current.pt) {
      const dx = x - lastRef.current.pt.x, dy = y - lastRef.current.pt.y;
      if (dx * dx + dy * dy < 380) return;
    }
    lastRef.current = { t: now, pt: { x, y } };
    const size = 60 + Math.random() * 70;
    const id = ++ridRef.current;
    setRipples(rs => [...rs, { id, x, y, size }].slice(-14));
    setTimeout(() => setRipples(rs => rs.filter(r => r.id !== id)), 950);
  };
  const onLeave = () => { lastRef.current.pt = null; };

  return (
    <div className={className} onMouseMove={onMove} onMouseLeave={onLeave} style={style}>
      <div style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 5 }}>
        {ripples.map(r => (
          <span key={r.id} style={{
            position: "absolute", left: r.x, top: r.y, width: r.size, height: r.size,
            borderRadius: "50%", border: "1.5px solid rgba(255,255,255,.85)",
            background: "radial-gradient(circle, rgba(255,255,255,.28), transparent 68%)",
            transform: "translate(-50%,-50%)", animation: "acc-ripple .9s ease-out forwards",
          }} />
        ))}
      </div>
      {children}
    </div>
  );
}

// ─ Upload zone (glass dropzone) ───────────────────────────────────────────
// ─ Shared file-drop behaviour for every upload box in the app ────────────
const AUDIO_EXT = /\.(mp3|wav|m4a|aac|ogg|oga|opus|flac|webm|mp4)$/i;
const isAudioFile = (f) => (f.type || "").startsWith("audio/") || AUDIO_EXT.test(f.name || "");

// Some sources (certain browsers, apps and download bars) leave dataTransfer
// .files empty and only expose the file through .items, so try both.
function firstFileFromDrop(dt) {
  if (!dt) return null;
  if (dt.files && dt.files.length) return dt.files[0];
  const items = dt.items ? Array.from(dt.items) : [];
  for (const it of items) {
    if (it.kind === "file" && it.getAsFile) { const f = it.getAsFile(); if (f) return f; }
  }
  return null;
}

function useFileDrop(onFile) {
  const [drag, setDrag] = useState(false);
  const [rejected, setRejected] = useState(null);
  const depth = useRef(0);   // dragenter/leave also fire for child elements
  const handlers = {
    // dragenter must be cancelled as well as dragover: Firefox and Safari
    // otherwise treat the page itself as the drop target.
    onDragEnter: (e) => { e.preventDefault(); depth.current += 1; setDrag(true); },
    onDragOver: (e) => { e.preventDefault(); if (e.dataTransfer) e.dataTransfer.dropEffect = "copy"; },
    onDragLeave: () => { depth.current = Math.max(0, depth.current - 1); if (depth.current === 0) setDrag(false); },
    onDrop: (e) => {
      e.preventDefault();
      depth.current = 0; setDrag(false);
      const f = firstFileFromDrop(e.dataTransfer);
      if (!f) return;
      if (!isAudioFile(f)) { setRejected(`"${f.name}" isn't an audio file. Drop a WAV, MP3 or M4A.`); return; }
      setRejected(null);
      onFile(f);
    },
  };
  return { drag, rejected, clearRejected: () => setRejected(null), handlers };
}

function UploadZone({ label, sub, onFile, file, accept = "audio/*,.mp3,.wav,.m4a,.aac,.ogg", glass = false, variant }) {
  const ref = useRef();
  const { drag, rejected, clearRejected, handlers: dropHandlers } = useFileDrop(onFile);
  const [previewUrl, setPreviewUrl] = useState(null);

  useEffect(() => {
    if (!file) { setPreviewUrl(null); return; }
    const u = URL.createObjectURL(file);
    setPreviewUrl(u);
    return () => URL.revokeObjectURL(u);
  }, [file]);

  // New-design dashed box: empty shows the upload prompt, filled shows the
  // pill player plus the filename and a clear button.
  if (variant === "dashed") {
    return (
      <>
        <input ref={ref} type="file" accept={accept} style={{ display: "none" }}
          onChange={e => e.target.files[0] && onFile(e.target.files[0])} />
        <DashedBox
          onClick={file ? undefined : () => ref.current?.click()}
          {...dropHandlers}
          style={{ minHeight: 300, borderColor: drag ? C.green : undefined, background: drag ? "var(--acc-green-light)" : undefined }}
        >
          {!file ? (
            <>
              <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke={C.text} strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round"><path d="M12 16V4M7 9l5-5 5 5M4 20h16"/></svg>
              <div style={{ marginTop: 16, font: `700 18px ${C.font}`, color: C.text }}>{label}</div>
              <div style={{ marginTop: 9, fontSize: 16, color: C.sub }}>{sub}</div>
              {rejected && <div style={{ marginTop: 14, fontSize: 14, color: C.error, textAlign: "center" }}>{rejected}</div>}
            </>
          ) : (
            <>
              <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                <PillPlayer url={previewUrl} />
                <button onClick={e => { e.stopPropagation(); onFile(null); }} aria-label="Remove file" style={{
                  width: 28, height: 28, borderRadius: "50%", border: "none", background: "transparent",
                  color: C.text, cursor: "pointer", flexShrink: 0, padding: 0,
                }}>
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><path d="M8.5 8.5l7 7M15.5 8.5l-7 7"/></svg>
                </button>
              </div>
              <div style={{ marginTop: 16, fontSize: 16, color: C.sub }}>{file.name}</div>
            </>
          )}
        </DashedBox>
      </>
    );
  }

  return (
    <div
      onClick={() => ref.current?.click()}
      {...dropHandlers}
      style={glass ? {
        display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
        gap: 11, padding: "40px 20px", borderRadius: 16, textAlign: "center", cursor: "pointer",
        transition: "all 0.15s",
        background: `rgba(255,255,255,${drag ? ".9" : ".6"})`,
        border: `2px dashed ${drag ? C.green : "rgba(20,55,35,.18)"}`,
      } : {
        border: `2px dashed ${drag ? C.green : file ? C.greenBorder : C.borderSolid}`,
        borderRadius: 14, padding: "30px 20px", cursor: "pointer",
        background: drag ? "#eef8f1" : file ? C.greenLight : "#fbfcfb",
        transition: "all 0.15s", textAlign: "center",
      }}
    >
      <input ref={ref} type="file" accept={accept} style={{ display: "none" }}
        onChange={e => e.target.files[0] && onFile(e.target.files[0])} />
      <div style={{
        width: glass ? 56 : 48, height: glass ? 56 : 48, borderRadius: glass ? 15 : 13,
        background: glass ? "rgba(255,255,255,.85)" : (file ? C.greenLight : "#f3f5f3"),
        border: glass ? "1px solid rgba(20,55,35,.08)" : "none",
        boxShadow: glass ? "0 6px 16px -8px rgba(19,122,68,.35)" : "none",
        display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, margin: glass ? "0 auto" : "0 auto 10px",
      }}>
        {file ? "🎵" : "↑"}
      </div>
      <div style={{ fontSize: 15.5, fontWeight: 700, color: file ? (glass ? C.text : C.green) : C.text, marginBottom: 4 }}>
        {file ? file.name : label}
      </div>
      <div style={{ fontSize: 12.5, color: C.muted }}>
        {file ? `${(file.size / 1024).toFixed(0)} KB · click to replace` : sub}
      </div>
      {rejected && <div style={{ marginTop: 8, fontSize: 12.5, color: C.error }}>{rejected}</div>}
    </div>
  );
}

