// ─ Voice capture form — identical setup() logic to before (clone → verify
//   → delete check-clone), restyled into the Claude Design export's
//   idle / processing / ready glass card. ───────────────────────────────
// ─ Plays a short spoken preview of a saved library voice — plain TTS
// directly on that voice's own ID, no accent-anchor conversion needed since
// this is just "what does this voice sound like", not a real generation. ──
const VOICE_PREVIEW_TEXT = "Hi, this is a quick preview of this voice.";

function VoicePreviewButton({ voiceId, size = 34, variant = "icon" }) {
  const [state, setState] = useState("idle"); // idle | loading | playing | error
  const audioRef = useRef(null);

  useEffect(() => () => { audioRef.current?.pause(); }, []);

  const toggle = async (e) => {
    e.stopPropagation();
    if (state === "playing") {
      audioRef.current?.pause();
      setState("idle");
      return;
    }
    if (state === "loading") return;
    setState("loading");
    try {
      const blob = await generateChunkAudio(VOICE_PREVIEW_TEXT, voiceId);
      const url = URL.createObjectURL(blob);
      const audio = new Audio(url);
      audioRef.current = audio;
      audio.onended = () => setState("idle");
      audio.onerror = () => setState("error");
      await audio.play();
      setState("playing");
    } catch {
      setState("error");
      setTimeout(() => setState("idle"), 1800);
    }
  };

  const icon = state === "loading" ? (
    <svg width="13" height="13" viewBox="0 0 16 16" fill="none" style={{ animation: "acc-spin .8s linear infinite" }}><path d="M14 8A6 6 0 1 1 8 2" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" /></svg>
  ) : state === "playing" ? (
    <svg width="11" height="11" viewBox="0 0 16 16" fill="none"><rect x="3" y="3" width="4" height="10" rx="1" fill="currentColor" /><rect x="9" y="3" width="4" height="10" rx="1" fill="currentColor" /></svg>
  ) : state === "error" ? (
    <svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M8 5v4M8 11h.01" stroke={C.error} strokeWidth="1.8" strokeLinecap="round" /></svg>
  ) : (
    <svg width="12" height="12" viewBox="0 0 16 16" fill="none"><path d="M5.5 3.5v9l7-4.5-7-4.5z" fill="currentColor" /></svg>
  );

  if (variant === "pill") {
    return (
      <button
        onClick={toggle}
        title={state === "playing" ? "Stop preview" : "Preview this voice"}
        style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
          padding: "10px 16px", borderRadius: 999, border: `1px solid ${C.border}`,
          background: state === "playing" ? C.green : C.white, color: state === "playing" ? "#fff" : C.text,
          cursor: "pointer", font: `700 13px ${C.font}`, whiteSpace: "nowrap",
        }}
      >
        {icon}
        {state === "playing" ? "Stop" : "Preview"}
      </button>
    );
  }

  return (
    <button
      onClick={toggle}
      title={state === "playing" ? "Stop preview" : "Preview this voice"}
      style={{
        flexShrink: 0, width: size, height: size, borderRadius: "50%", border: `1px solid ${C.border}`,
        background: state === "playing" ? C.green : C.white, color: state === "playing" ? "#fff" : C.text,
        cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center",
      }}
    >
      {icon}
    </button>
  );
}

function VoiceCaptureForm({ onDone, buttonLabel = "Continue", accentLabel = "", userEmail, onBrowseLibrary }) {
  const [tab, setTab] = useState("upload");
  const [file, setFile] = useState(null);
  const [recordedBlob, setRecordedBlob] = useState(null);
  const [recordedDur, setRecordedDur] = useState(null);
  const [consent, setConsent] = useState(false);
  const [cleanupAudio, setCleanupAudio] = useState(false);
  const [loading, setLoading] = useState(false);
  const [done, setDone] = useState(false);
  const [error, setError] = useState(null);
  const [progress, setProgress] = useState("");

  // Shared voice library — fetched once when the tab is opened
  const [library, setLibrary] = useState(null);
  const [libraryLoading, setLibraryLoading] = useState(false);
  const [selectedLibraryVoice, setSelectedLibraryVoice] = useState(null);

  // "Save to library" — shown once a fresh clone is ready
  const [saveToLibrary, setSaveToLibrary] = useState(false);
  const [libraryVoiceName, setLibraryVoiceName] = useState("");
  const [libraryVoiceLanguage, setLibraryVoiceLanguage] = useState("English");
  const [libraryVoiceCategory, setLibraryVoiceCategory] = useState("");
  const [savingToLibrary, setSavingToLibrary] = useState(false);
  const [savedToLibrary, setSavedToLibrary] = useState(false);
  const [saveError, setSaveError] = useState(null);

  const VOICE_LIBRARY_CACHE_KEY = "accentuate_voice_library_cache";

  const loadLibrary = async () => {
    // Show cached data instantly, if we have any — no spinner, no wait.
    // We still refresh in the background so the list stays accurate.
    let hadCache = false;
    try {
      const cached = localStorage.getItem(VOICE_LIBRARY_CACHE_KEY);
      if (cached) {
        setLibrary(JSON.parse(cached));
        hadCache = true;
      }
    } catch { /* localStorage unavailable — fall through to a normal fetch */ }

    if (!hadCache) setLibraryLoading(true);
    const rows = await fetchVoiceLibrary();
    setLibrary(rows);
    setLibraryLoading(false);
    try { localStorage.setItem(VOICE_LIBRARY_CACHE_KEY, JSON.stringify(rows)); } catch { /* ignore quota errors */ }
  };

  // Prefetch in the background the moment this screen loads — Apps Script
  // has real round-trip latency, so starting early (before the user even
  // clicks the Library tab) makes it feel instant when they do.
  useEffect(() => { loadLibrary(); }, []); // eslint-disable-line

  const hasVoice = tab === "upload" ? !!file : !!recordedBlob;
  const sourceName = tab === "upload"
    ? (file ? file.name.replace(/\.[^/.]+$/, "") : null)
    : "My recording";

  const [resolvedFile, setResolvedFile] = useState(null);

  const setup = async () => {
    setLoading(true); setError(null); setProgress("");
    try {
      let audioFile;
      if (tab === "upload") {
        audioFile = file;
      } else {
        const ext = recordedBlob.type.includes("mp4") ? "mp4" : "webm";
        audioFile = new File([recordedBlob], `voice_recording.${ext}`, { type: recordedBlob.type || "audio/webm" });
      }

      // Optional — clean up background noise before cloning
      if (cleanupAudio) {
        setProgress("Cleaning up audio...");
        audioFile = await isolateVoice(audioFile);
      }

      // Quick validation clone to confirm the sample works, then delete it.
      // The sample itself is what gets stored — cloning happens fresh per generation.
      setProgress("Setting up your voice...");
      const voiceId = await cloneVoice(audioFile, `accentuate_check_${Date.now()}`);
      await deleteVoice(voiceId).catch(() => {});
      setResolvedFile(audioFile);
      setDone(true);
      setLoading(false);
    } catch (e) {
      setError(e.message || "Voice setup failed. Check your audio sample and try again.");
      setLoading(false);
    }
  };

  // Reset the whole local form — used by "Use a different sample" in the ready state
  const resetForm = () => {
    setFile(null); setRecordedBlob(null); setRecordedDur(null);
    setConsent(false); setCleanupAudio(false);
    setDone(false); setError(null); setProgress(""); setResolvedFile(null);
    setSaveToLibrary(false); setLibraryVoiceName(""); setSavedToLibrary(false); setSaveError(null);
  };

  const removeSample = () => { setFile(null); setRecordedBlob(null); setRecordedDur(null); };

  // Saving to the library means a real, permanent clone — not the disposable
  // check-then-delete clone used for validation. Visible to every user.
  const saveCurrentVoiceToLibrary = async () => {
    if (!libraryVoiceName.trim() || !resolvedFile) return;
    setSavingToLibrary(true); setSaveError(null);
    try {
      const voiceId = await cloneVoice(resolvedFile, libraryVoiceName.trim());
      await saveVoiceToLibrary({ voiceId, name: libraryVoiceName.trim(), addedBy: userEmail || "unknown", language: libraryVoiceLanguage, category: libraryVoiceCategory });
      setSavedToLibrary(true);
      loadLibrary(); // refresh so the new voice appears immediately, cache included
    } catch (e) {
      setSaveError(e.message || "Couldn't save this voice to the library. Try again.");
    }
    setSavingToLibrary(false);
  };

  const continueEnabled = hasVoice && consent && !loading;

  return (
    <div style={{ position: "relative", width: "100%", maxWidth: 434, background: C.glassStrong, backdropFilter: "blur(22px) saturate(1.5)", WebkitBackdropFilter: "blur(22px) saturate(1.5)", border: `1px solid rgba(255,255,255,.6)`, borderRadius: 24, boxShadow: "0 34px 70px -28px rgba(20,55,35,.35), inset 0 1px 1px rgba(255,255,255,.7), inset 0 -1px 3px rgba(255,255,255,.25)", padding: 22, zIndex: 10 }}>

      {/* IDLE */}
      {!loading && !done && (
        <div>
          <SegToggle
            active={tab}
            onChange={t => {
              setTab(t); setFile(null); setRecordedBlob(null);
              if (t === "library" && library === null) loadLibrary();
            }}
            options={[
              { id: "upload", label: "Upload file", icon: <svg width="14" height="14" viewBox="0 0 16 16" fill="none"><path d="M8 11V3M8 3L4.5 6.5M8 3l3.5 3.5M3 13h10" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" /></svg> },
              { id: "record", label: "Record voice", icon: <svg width="13" height="13" viewBox="0 0 16 16" fill="none"><rect x="5.5" y="1.5" width="5" height="9" rx="2.5" stroke="currentColor" strokeWidth="1.5" /><path d="M3 7.5a5 5 0 0 0 10 0M8 12.5V14.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /></svg> },
              { id: "library", label: "Voice library", icon: <svg width="13" height="13" viewBox="0 0 16 16" fill="none"><rect x="2" y="3" width="12" height="10" rx="2" stroke="currentColor" strokeWidth="1.5" /><path d="M5 6.5h6M5 9.5h4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /></svg> },
            ]}
          />

          {tab === "library" && (
            <div style={{ marginTop: 14 }}>
              {onBrowseLibrary && (
                <button onClick={onBrowseLibrary} style={{
                  width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
                  padding: "11px 14px", borderRadius: 999, marginBottom: 12,
                  border: `1px solid ${C.greenBorder}`, background: "#eef8f1", color: C.green,
                  font: `700 13px ${C.font}`, cursor: "pointer",
                }}>
                  <svg width="14" height="14" viewBox="0 0 16 16" fill="none"><rect x="2" y="3" width="12" height="10" rx="2" stroke="currentColor" strokeWidth="1.5" /><path d="M5 6.5h6M5 9.5h4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /></svg>
                  Browse full library
                </button>
              )}
              {libraryLoading && (
                <div style={{ textAlign: "center", padding: "24px 0" }}>
                  <ProcessingWave height={36} />
                  <div style={{ fontSize: 13, color: C.muted, marginTop: 10 }}>Loading voice library...</div>
                </div>
              )}
              {!libraryLoading && library && library.length === 0 && (
                <div style={{ textAlign: "center", padding: "20px 0", fontSize: 13.5, color: C.muted }}>
                  No saved voices yet. Upload or record one, then save it here for next time.
                </div>
              )}
              {!libraryLoading && library && library.length > 0 && (
                <div style={{ display: "flex", flexDirection: "column", gap: 8, maxHeight: 260, overflowY: "auto" }}>
                  {library.map((v) => {
                    const isSelected = selectedLibraryVoice?.["Voice ID"] === v["Voice ID"];
                    const isAdmin = LIBRARY_ADMIN_EMAILS.includes(userEmail);
                    return (
                      <div key={v["Voice ID"]} style={{
                        display: "flex", alignItems: "center", gap: 8,
                        border: `1.5px solid ${isSelected ? C.green : "rgba(0,0,0,.1)"}`,
                        background: isSelected ? "#eef8f1" : "rgba(255,255,255,.6)",
                        borderRadius: 12,
                      }}>
                        <div style={{ paddingLeft: 10 }}><VoicePreviewButton voiceId={v["Voice ID"]} /></div>
                        <button onClick={() => setSelectedLibraryVoice(v)} style={{
                          flex: 1, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10,
                          padding: "12px 14px", textAlign: "left", cursor: "pointer", border: "none", background: "none",
                        }}>
                          <div>
                            <div style={{ fontSize: 14, fontWeight: 700, color: C.text }}>{v.Name}</div>
                            <div style={{ fontSize: 11.5, color: C.muted }}>Added by {v.AddedBy || "unknown"}</div>
                          </div>
                          {isSelected && (
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none"><path d="M5 12.5L10 17.5L19 7" stroke={C.green} strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" /></svg>
                          )}
                        </button>
                        {isAdmin && (
                          <button
                            onClick={async (e) => {
                              e.stopPropagation();
                              if (!window.confirm(`Remove "${v.Name}" from the library? This deletes it from ElevenLabs too.`)) return;
                              await deleteVoice(v["Voice ID"]).catch(() => {});
                              await removeVoiceFromLibrary(v["Voice ID"]);
                              if (selectedLibraryVoice?.["Voice ID"] === v["Voice ID"]) setSelectedLibraryVoice(null);
                              loadLibrary();
                            }}
                            style={{
                              flexShrink: 0, width: 30, height: 30, marginRight: 8, borderRadius: 8, border: "none",
                              background: "rgba(0,0,0,.05)", color: C.sub, cursor: "pointer", fontSize: 15,
                              display: "flex", alignItems: "center", justifyContent: "center",
                            }}
                            title="Remove from library"
                          >×</button>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}

          {tab !== "library" && (
            <>
              <UploadZone glass label="Drop a voice sample here" sub="WAV · MP3 · M4A — 1 to 2 minutes recommended" onFile={f => { setError(null); setFile(f); }} file={null} />

              {tab === "record" && !recordedBlob && (
                <VoiceRecorder glass onBlob={b => { setRecordedBlob(b); }} />
              )}

              {hasVoice && (
                <div style={{ display: "flex", alignItems: "center", gap: 12, padding: 16, borderRadius: 14, border: `1px solid ${C.greenBorder}`, background: "#eef8f1" }}>
                  <SampleIcon size={40} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 14, fontWeight: 700, color: C.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                      {tab === "upload" ? file.name : "Voice recording"}
                    </div>
                    <div style={{ fontSize: 12, color: "#5b8f70" }}>Ready to clone</div>
                  </div>
                  <button onClick={removeSample} style={{ width: 28, height: 28, borderRadius: 8, border: "none", background: "#fff", color: C.sub, cursor: "pointer", fontSize: 16, lineHeight: 1, display: "flex", alignItems: "center", justifyContent: "center" }}>×</button>
                </div>
              )}

              {hasVoice && (
                <label onClick={() => setCleanupAudio(v => !v)} style={{ display: "flex", gap: 11, alignItems: "flex-start", marginTop: 14, cursor: "pointer", padding: 14, border: "1px solid rgba(0,0,0,.1)", borderRadius: 14, background: "rgba(255,255,255,.5)" }}>
                  <div style={{ width: 20, height: 20, flexShrink: 0, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", border: cleanupAudio ? "none" : "1.5px solid #cdd1cd", background: cleanupAudio ? C.green : "#fff" }}>
                    {cleanupAudio && <svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M2.5 7.5L5.5 10.5L11.5 3.5" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>}
                  </div>
                  <span style={{ fontSize: 12.5, lineHeight: 1.5, color: C.sub2 }}><b style={{ color: C.text, fontWeight: 700 }}>Clean up background noise</b> — reduces hiss, echo, and ambient sound from your sample before cloning. Recommended for recordings made outside a quiet room.</span>
                </label>
              )}

              <label onClick={() => setConsent(v => !v)} style={{ display: "flex", gap: 11, alignItems: "flex-start", marginTop: 14, cursor: "pointer", padding: 14, border: "1px solid rgba(0,0,0,.1)", borderRadius: 14, background: "rgba(255,255,255,.5)" }}>
                <div style={{ width: 20, height: 20, flexShrink: 0, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", border: consent ? "none" : "1.5px solid #cdd1cd", background: consent ? C.green : "#fff" }}>
                  {consent && <svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M2.5 7.5L5.5 10.5L11.5 3.5" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>}
                </div>
                <span style={{ fontSize: 12.5, lineHeight: 1.5, color: C.sub2 }}>
                  I confirm I have the right to use this voice sample and will not use generated content for
                  illegal, fraudulent, harmful, or non-consensual purposes. I agree to Accentuate's{" "}
                  <a href="/terms.html" target="_blank" rel="noopener noreferrer" onClick={e => e.stopPropagation()} style={{ color: C.green, fontWeight: 700, textDecoration: "underline" }}>Terms &amp; Privacy Policy</a>.
                </span>
              </label>

              <ErrorBox msg={error} />

              <button onClick={setup} disabled={!continueEnabled} style={{
                width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
                padding: 14, border: "none", borderRadius: 999, font: `700 15px ${C.font}`, transition: "all 0.15s", marginTop: 16,
                background: continueEnabled ? C.green : "#eef0ee", color: continueEnabled ? "#fff" : "#b3b8b3",
                cursor: continueEnabled ? "pointer" : "not-allowed",
                boxShadow: continueEnabled ? C.greenGlow : "none",
              }}>{buttonLabel}</button>
            </>
          )}

          {tab === "library" && selectedLibraryVoice && (
            <button onClick={() => onDone(selectedLibraryVoice["Voice ID"], selectedLibraryVoice.Name)} style={{
              width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
              padding: 14, border: "none", borderRadius: 999, font: `700 15px ${C.font}`, marginTop: 16,
              background: C.green, color: "#fff", cursor: "pointer", boxShadow: C.greenGlow,
            }}>{buttonLabel}</button>
          )}

          {tab === "library" && (
            <p style={{ fontSize: 12, color: C.muted, textAlign: "center", marginTop: 14, lineHeight: 1.6 }}>
              Library voices are shared and visible to every user — no re-cloning needed.
            </p>
          )}
        </div>
      )}

      {/* PROCESSING */}
      {loading && (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 20, padding: "40px 20px" }}>
          <ProcessingWave />
          <div style={{ fontSize: 16, fontWeight: 800, color: C.text, letterSpacing: "-0.01em" }}>Setting up your voice…</div>
          <div style={{ fontSize: 13, color: C.muted, transition: "opacity .3s" }}>{progress || "Analysing vocal characteristics..."}</div>
        </div>
      )}

      {/* READY */}
      {done && (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 14, padding: "30px 20px 12px", textAlign: "center", animation: "acc-fadein .45s ease both" }}>
          <div style={{ width: 54, height: 54, borderRadius: "50%", background: C.green, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 12px 26px -10px rgba(19,122,68,.7)" }}>
            <svg width="26" height="26" viewBox="0 0 24 24" fill="none"><path d="M5 12.5L10 17.5L19 7" stroke="#fff" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" /></svg>
          </div>
          <div style={{ fontSize: 18, fontWeight: 800, color: C.text, letterSpacing: "-0.01em" }}>Your voice is ready</div>
          <div style={{ fontSize: 13.5, lineHeight: 1.5, color: C.sub2, maxWidth: 300 }}>Your {accentLabel} voice is ready. Start generating audio that sounds authentic.</div>
          <button onClick={() => onDone(resolvedFile, sourceName)} style={{
            width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, padding: 14,
            border: "none", borderRadius: 999, background: C.green, color: "#fff", font: `700 15px ${C.font}`,
            cursor: "pointer", marginTop: 6, boxShadow: C.greenGlow,
          }}>Proceed</button>
          <button onClick={resetForm} style={{ background: "none", border: "none", color: C.muted2, font: `600 13px ${C.font}`, cursor: "pointer", textDecoration: "underline" }}>
            Use a different sample
          </button>

          {/* Optional — save this voice to the shared library for next time */}
          {!savedToLibrary ? (
            !saveToLibrary ? (
              <button onClick={() => setSaveToLibrary(true)} style={{
                width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
                padding: "11px 14px", borderRadius: 999, marginTop: 4,
                border: "1px dashed rgba(0,0,0,.15)", background: "none", color: C.green,
                font: `700 13px ${C.font}`, cursor: "pointer",
              }}>
                <svg width="14" height="14" viewBox="0 0 16 16" fill="none"><path d="M8 3v10M3 8h10" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" /></svg>
                Save this voice to the library
              </button>
            ) : (
              <div style={{ width: "100%", textAlign: "left", marginTop: 4, padding: 14, borderRadius: 14, border: "1px solid rgba(0,0,0,.1)", background: "rgba(255,255,255,.5)" }}>
                <p style={{ fontSize: 12, lineHeight: 1.55, color: C.sub2, marginBottom: 10 }}>
                  This makes the voice permanently available to <b>everyone</b> using Accentuate — not just you. Only save voices you have the right to share.
                </p>
                <input
                  value={libraryVoiceName}
                  onChange={e => setLibraryVoiceName(e.target.value)}
                  placeholder="Name this voice (e.g. Tunde — Narrator)"
                  style={{ width: "100%", padding: "10px 12px", borderRadius: 10, border: "1px solid rgba(0,0,0,.12)", background: "#fff", font: `500 13.5px ${C.font}`, color: C.text, outline: "none", boxSizing: "border-box", marginBottom: 10 }}
                />
                <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
                  <select
                    value={libraryVoiceLanguage}
                    onChange={e => setLibraryVoiceLanguage(e.target.value)}
                    style={{ flex: 1, padding: "10px 12px", borderRadius: 10, border: "1px solid rgba(0,0,0,.12)", background: "#fff", font: `500 13px ${C.font}`, color: C.text, outline: "none" }}
                  >
                    {VOICE_LANGUAGES.map(l => <option key={l} value={l}>{l}</option>)}
                  </select>
                  <select
                    value={libraryVoiceCategory}
                    onChange={e => setLibraryVoiceCategory(e.target.value)}
                    style={{ flex: 1, padding: "10px 12px", borderRadius: 10, border: "1px solid rgba(0,0,0,.12)", background: "#fff", font: `500 13px ${C.font}`, color: libraryVoiceCategory ? C.text : "#9aa09b", outline: "none" }}
                  >
                    <option value="">Category (optional)</option>
                    {VOICE_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <ErrorBox msg={saveError} />
                <button onClick={saveCurrentVoiceToLibrary} disabled={!libraryVoiceName.trim() || savingToLibrary} style={{
                  width: "100%", padding: 11, borderRadius: 999, border: "none", font: `700 13px ${C.font}`,
                  background: (!libraryVoiceName.trim() || savingToLibrary) ? "#eef0ee" : C.green,
                  color: (!libraryVoiceName.trim() || savingToLibrary) ? "#b3b8b3" : "#fff",
                  cursor: (!libraryVoiceName.trim() || savingToLibrary) ? "not-allowed" : "pointer",
                }}>{savingToLibrary ? "Saving..." : "Confirm and save"}</button>
              </div>
            )
          ) : (
            <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12.5, color: "#5b8f70", fontWeight: 700, marginTop: 4 }}>
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none"><path d="M5 12.5L10 17.5L19 7" stroke="#5b8f70" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" /></svg>
              Saved to the voice library
            </div>
          )}
        </div>
      )}
    </div>
  );
}

