// Right rail contents shared by all four tools.
function ToolRail({
  countryConfig, accent, onAccentChange, accentLabel,
  voiceSlots, onOpenPicker, onAddVoice, canAddVoice,
  resultUrl, resultReady, downloadName, downloadExt, active,
  wordCount = 0,
}) {
  // The rail owns speed so it can apply a real, pitch-preserving stretch to
  // the generated audio — which is also what gives "Match 100 WPM" a true
  // duration to aim at, in every tool rather than just Generate Script.
  const [speed, setSpeed] = useState(1);
  const [adjustedUrl, setAdjustedUrl] = useState(null);
  const [baseDuration, setBaseDuration] = useState(0);
  const [stretching, setStretching] = useState(false);
  const [wpmNote, setWpmNote] = useState(null);
  const reqRef = useRef(0);

  useEffect(() => {
    setSpeed(1); setWpmNote(null);
    setAdjustedUrl(prev => { if (prev) URL.revokeObjectURL(prev); return null; });
    if (!resultUrl) { setBaseDuration(0); return; }
    const probe = new Audio(resultUrl);
    probe.addEventListener("loadedmetadata", () => setBaseDuration(probe.duration || 0));
  }, [resultUrl]);

  useEffect(() => {
    if (!resultUrl) return;
    const id = ++reqRef.current;
    if (Math.abs(speed - 1) < 0.001) {
      setAdjustedUrl(prev => { if (prev) URL.revokeObjectURL(prev); return null; });
      return;
    }
    let cancelled = false;
    setStretching(true);
    (async () => {
      try {
        const blob = await fetch(resultUrl).then(r => r.blob());
        const out = await stretchAudioBlob(blob, speed);
        if (cancelled || id !== reqRef.current) return;
        setAdjustedUrl(prev => { if (prev) URL.revokeObjectURL(prev); return URL.createObjectURL(out); });
      } catch { /* keep the original on failure */ }
      finally { if (!cancelled) setStretching(false); }
    })();
    return () => { cancelled = true; };
  }, [speed, resultUrl]);

  const playUrl = adjustedUrl || resultUrl;
  const playDuration = baseDuration ? baseDuration / speed : 0;

  // Work out the extension from the ACTUAL data rather than assuming mp3.
  // Scripts long enough to be chunked come back as WAV (they're decoded and
  // re-concatenated), and stretched audio is always WAV — labelling either
  // as .mp3 produces a file players mis-read, which can sound like the audio
  // stops early.
  const [ext, setExt] = useState(downloadExt || "mp3");
  useEffect(() => {
    if (!playUrl) { setExt(downloadExt || "mp3"); return; }
    let cancelled = false;
    fetch(playUrl)
      .then(r => r.blob())
      .then(b => {
        if (cancelled) return;
        const type = (b.type || "").toLowerCase();
        setExt(type.includes("wav") ? "wav" : type.includes("mpeg") || type.includes("mp3") ? "mp3" : (downloadExt || "mp3"));
      })
      .catch(() => {});
    return () => { cancelled = true; };
  }, [playUrl, downloadExt]);

  const matchWPM = () => {
    if (!wordCount || !baseDuration) return;
    const ideal = (wordCount / 100) * 60;       // seconds needed for 100 WPM
    const raw = baseDuration / ideal;           // >1 means the clip must speed up
    // Only ever speed up: if the clip already runs at or above 100 WPM,
    // slowing it down to hit the target would hurt the delivery, so hold at 1x.
    if (raw <= 1.005) {
      setSpeed(1);
      setWpmNote("Already at or above 100 WPM — left at 1× rather than slowing it down.");
      return;
    }
    const clamped = Math.min(2, raw);
    setSpeed(Math.round(clamped * 100) / 100);
    setWpmNote(clamped < raw - 0.01
      ? "100 WPM needs more than 2× for this clip — set to the fastest available speed."
      : null);
  };

  return (
    <>
      {countryConfig.hasAccentToggle ? (
        <>
          <div style={{ fontSize: 14, color: C.sub }}>Voice Type</div>
          <div role="tablist" aria-label="Voice type" style={{ display: "flex", gap: 26, marginTop: 12, borderBottom: `1px solid ${C.border}` }}>
            {Object.entries(ANCHOR_VOICES).map(([key, v]) => {
              const on = accent === key;
              return (
                <button key={key} role="tab" aria-selected={on} onClick={() => onAccentChange(key)} style={{
                  all: "unset", cursor: "pointer", fontSize: 17, paddingBottom: 12, marginBottom: -1,
                  fontWeight: on ? 700 : 400, color: on ? C.green : C.sub,
                  borderBottom: on ? `2px solid ${C.green}` : "2px solid transparent",
                }}>{v.label}</button>
              );
            })}
          </div>
          <p style={{ margin: "22px 0 0", fontSize: 17, lineHeight: 1.45, color: C.text }}>
            {ANCHOR_VOICES[accent].desc}
          </p>
        </>
      ) : (
        <p style={{ margin: 0, fontSize: 16, color: C.sub }}>Using the {accentLabel} anchor voice.</p>
      )}

      <div style={{ marginTop: 32 }}>
        {voiceSlots.map(slot => (
          <div key={slot.key} style={{ marginBottom: 18 }}>
            <div style={{ fontSize: 14, color: C.sub, marginBottom: 11 }}>{slot.label}</div>
            <button onClick={slot.onClick} style={{
              width: "100%", height: 54, boxSizing: "border-box", border: `1px solid ${slot.empty ? C.borderSolid : C.text}`,
              borderRadius: 9, background: C.white, display: "flex", alignItems: "center", justifyContent: "space-between",
              padding: "0 16px", cursor: "pointer", textAlign: "left",
            }}>
              <span style={{ font: `400 17px ${C.font}`, color: slot.empty ? C.muted : C.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                {slot.value || "Select Voice"}
              </span>
              {slot.empty
                ? <svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke={C.text} strokeWidth="1.5" style={{ flexShrink: 0 }}><circle cx="12" cy="12" r="10"/><path d="M12 8v8M8 12h8" strokeLinecap="round"/></svg>
                : <svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke={C.text} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}><circle cx="12" cy="12" r="10"/><path d="M8 12h8M13 8l4 4-4 4"/></svg>}
            </button>
          </div>
        ))}
        {onAddVoice && canAddVoice && (
          <button onClick={onAddVoice} style={{
            display: "flex", alignItems: "center", gap: 11, background: "none", border: "none", padding: 0,
            cursor: "pointer", font: `400 17px ${C.font}`, color: C.text, marginTop: 4,
          }}>
            <svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"><circle cx="12" cy="12" r="10"/><path d="M12 8v8M8 12h8" strokeLinecap="round"/></svg>
            Add another voice
          </button>
        )}
      </div>

      <div style={{ flexGrow: 1, minHeight: 24 }} />

      {resultUrl && (
        <div style={{ marginBottom: 26 }}>
          <SpeedControl
            value={speed} onChange={v => { setSpeed(v); setWpmNote(null); }}
            wordCount={wordCount} duration={playDuration}
            onMatchWPM={matchWPM} wpmNote={wpmNote}
          />
          {stretching && <div style={{ fontSize: 12, color: C.sub, marginTop: 8 }}>Applying speed…</div>}
        </div>
      )}

      {resultReady && <div style={{ fontSize: 17, color: C.text, marginBottom: 14 }}>Your audio is ready</div>}
      <PillPlayer url={playUrl} size="lg" active={active} />
      <DownloadBar url={playUrl} defaultName={downloadName} ext={ext} disabled={!playUrl} />
    </>
  );
}

function TextToVoice({ voiceSample, voiceName, country, charLimit, onBack, onUseAnother, onStartOver, active = true, requireLessonLog = false, userEmail, onChangeVoice }) {
  const [text, setText] = useState("");
  const [accent, setAccent] = useState(DEFAULT_ACCENT);
  const [speed] = useState(1.0);   // generation-time speed; playback speed lives in ToolRail
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState("");
  const [audioUrl, setAudioUrl] = useState(null);
  const [error, setError] = useState(null);
  const [showVoicePicker, setShowVoicePicker] = useState(false);

  const cancelledRef = useRef(false);
  const countryConfig = COUNTRIES[country];

  const generate = async () => {
    if (!text.trim()) return;
    setLoading(true); setError(null); setAudioUrl(null); setProgress("");
    cancelledRef.current = false;
    try {
      const anchorVoiceId = countryConfig.hasAccentToggle
        ? ANCHOR_VOICES[accent].id
        : countryConfig.anchorId;
      const isDirect = countryConfig.hasAccentToggle && anchorVoiceId === null;

      const normalizedText = normalizeTextForTTS(text.trim());
      const chunks = chunkScript(normalizedText, 2000);
      // One seed shared across every chunk of this generation — keeps the
      // accent's delivery consistent between chunks instead of each one
      // being an independent, unrelated roll of ElevenLabs' randomness.
      const generationSeed = Math.floor(Math.random() * 4294967295);

      if (isDirect) {
        // Direct — no accent anchor, no voice conversion step. The cloned
        // voice generates the speech itself, in whatever accent is
        // actually present in the original sample.
        await withClonedVoice(voiceSample, async (vId) => {
          const chunkBlobs = [];
          for (let i = 0; i < chunks.length; i++) {
            if (cancelledRef.current) return;
            setProgress(chunks.length > 1 ? `Generating part ${i + 1} of ${chunks.length}...` : "Generating your audio...");
            chunkBlobs.push(await generateChunkAudio(chunks[i], vId, speed, generationSeed));
          }
          if (cancelledRef.current) return;
          setProgress(chunks.length > 1 ? "Combining audio sections..." : "");
          const finalBlob = await concatenateAudioBlobs(chunkBlobs);
          if (cancelledRef.current) return;
          setAudioUrl(URL.createObjectURL(finalBlob));
        });
      } else {
        const chunkBlobs = [];
        for (let i = 0; i < chunks.length; i++) {
          if (cancelledRef.current) return;
          setProgress(
            chunks.length > 1
              ? `Generating part ${i + 1} of ${chunks.length}...`
              : "Generating your audio..."
          );
          const blob = await generateChunkAudio(chunks[i], anchorVoiceId, speed, generationSeed);
          chunkBlobs.push(blob);
        }

        if (cancelledRef.current) return;

        setProgress(chunks.length > 1 ? "Combining audio sections..." : "Applying your voice...");
        const anchorBlob = await concatenateAudioBlobs(chunkBlobs);

        if (cancelledRef.current) return;

        setProgress("Applying your voice...");
        const finalBlob = await withClonedVoice(voiceSample, vId => voiceChangerFromBlob(anchorBlob, vId));

        if (cancelledRef.current) return;

        setAudioUrl(URL.createObjectURL(finalBlob));
      }

      setProgress("");
      logUsageEntry({ email: userEmail, mode: "Generate Script", characters: normalizedText.length });
    } catch (e) {
      if (!cancelledRef.current) setError(e.message || "Generation failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const cancel = () => {
    cancelledRef.current = true;
    setLoading(false); setProgress(""); setError(null);
  };

  const words = text.trim() ? text.trim().split(/\s+/).length : 0;
  const overLimit = charLimit && text.length > charLimit;
  const canGenerate = !!text.trim() && !overLimit && !loading;

  return (
    <ToolLayout rail={
      <ToolRail
        countryConfig={countryConfig}
        accent={accent} onAccentChange={setAccent}
        accentLabel={countryConfig.label.replace(" Accent", "")}
        voiceSlots={[{ key: "a", label: "Selected Voice", value: voiceName, onClick: () => setShowVoicePicker(true) }]}
        resultUrl={audioUrl} resultReady={!!audioUrl}
        downloadName="accentuate_script" active={active}
        wordCount={words}
      />
    }>
      {loading ? (
        <div style={{ flexGrow: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 18, textAlign: "center" }}>
          <ProcessingWave />
          <div style={{ fontSize: 18, fontWeight: 800, color: C.text }}>{progress || "Applying your voice…"}</div>
          <div style={{ fontSize: 13.5, color: C.muted, maxWidth: 340 }}>Longer scripts are generated in sections and combined automatically</div>
          <button onClick={cancel} style={{ marginTop: 4, padding: "11px 30px", borderRadius: 999, border: `1px solid ${C.borderSolid}`, background: C.white, color: C.text, font: `600 14px ${C.font}`, cursor: "pointer" }}>Cancel</button>
        </div>
      ) : (
        <textarea
          value={text} onChange={e => setText(e.target.value)} placeholder="Type or paste your script here"
          style={{
            flexGrow: 1, minHeight: 300, width: "100%", boxSizing: "border-box", border: "none", outline: "none",
            resize: "none", padding: 0, fontSize: 19, lineHeight: 1.55, color: C.text, background: "transparent", fontFamily: C.font,
          }}
        />
      )}

      <ErrorBox msg={loading ? null : error} />
      {overLimit && (
        <div style={{ marginTop: 10, fontSize: 13, color: C.error }}>
          Script exceeds your {charLimit.toLocaleString()} character limit. Please shorten it to generate.
        </div>
      )}

      <ToolFooter
        meta={`${text.length} Characters / ${words} words`}
        actionLabel={audioUrl ? "Generate Again" : "Generate Audio"}
        onAction={generate}
        disabled={!canGenerate}
      />

      {showVoicePicker && (
        <VoicePickerModal
          userEmail={userEmail}
          onClose={() => setShowVoicePicker(false)}
          onSelect={(sample, name) => { onChangeVoice && onChangeVoice(sample, name); setShowVoicePicker(false); }}
        />
      )}
    </ToolLayout>
  );
}

// ─ Screen: Convert Audio ────────────────────────────────────────────────
function ConvertAudio({ voiceSample, voiceName, country, charLimit, durationLimit, onBack, onUseAnother, onStartOver, active = true, requireLessonLog = false, userEmail, onChangeVoice }) {
  const [showVoicePicker, setShowVoicePicker] = useState(false);
  const [file, setFile] = useState(null);
  const [accent, setAccent] = useState(DEFAULT_ACCENT);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState("");
  const [audioUrl, setAudioUrl] = useState(null);
  const [error, setError] = useState(null);
  const [transcriptWordCount, setTranscriptWordCount] = useState(0);
  const countryConfig = COUNTRIES[country];
  const accentLabel = countryConfig ? countryConfig.label.replace(" Accent", "") : "";

  const convert = async () => {
    if (!file) return;
    setLoading(true); setError(null); setAudioUrl(null); setProgress("");
    try {
      const anchorVoiceId = countryConfig.hasAccentToggle
        ? ANCHOR_VOICES[accent].id
        : countryConfig.anchorId;

      // Check duration limit if applicable
      if (durationLimit) {
        const duration = await getAudioDuration(file);
        if (duration > durationLimit) {
          const mins = Math.floor(durationLimit / 60);
          throw new Error(`This recording is ${Math.floor(duration / 60)}m ${Math.floor(duration % 60)}s, which exceeds your ${mins} minute limit. Try a shorter recording.`);
        }
      }

      // Step 1 — Transcribe
      setProgress("Transcribing your audio...");
      const { text: transcript } = await transcribeAudio(file);
      setTranscriptWordCount(transcript.trim() ? transcript.trim().split(/\s+/).length : 0);

      // Check character limit if applicable
      if (charLimit && transcript.length > charLimit) {
        throw new Error(`The transcribed audio is ${transcript.length.toLocaleString()} characters, which exceeds your ${charLimit.toLocaleString()} character limit. Try a shorter recording.`);
      }

      const chunks = chunkScript(normalizeTextForTTS(transcript), 2000);
      const generationSeed = Math.floor(Math.random() * 4294967295);
      const isDirect = countryConfig.hasAccentToggle && anchorVoiceId === null;

      let finalBlob;
      if (isDirect) {
        // Direct — no accent anchor, no voice conversion step.
        finalBlob = await withClonedVoice(voiceSample, async (vId) => {
          const chunkBlobs = [];
          for (let i = 0; i < chunks.length; i++) {
            setProgress(chunks.length > 1 ? `Generating part ${i + 1} of ${chunks.length}...` : "Generating your audio...");
            chunkBlobs.push(await generateChunkAudio(chunks[i], vId, 1.0, generationSeed));
          }
          return await concatenateAudioBlobs(chunkBlobs);
        });
      } else {
        const chunkBlobs = [];
        for (let i = 0; i < chunks.length; i++) {
          setProgress(
            chunks.length > 1
              ? `Generating part ${i + 1} of ${chunks.length}...`
              : `Generating in ${accentLabel} accent...`
          );
          chunkBlobs.push(await generateChunkAudio(chunks[i], anchorVoiceId, 1.0, generationSeed));
        }
        const anchorBlob = await concatenateAudioBlobs(chunkBlobs);

        setProgress("Applying your voice...");
        finalBlob = await withClonedVoice(voiceSample, vId => voiceChangerFromBlob(anchorBlob, vId));
      }
      setAudioUrl(URL.createObjectURL(finalBlob));
      setProgress("");
      logUsageEntry({ email: userEmail, mode: "Convert Audio", characters: transcript.length });
    } catch (e) {
      setError(e.message || "Conversion failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <ToolLayout rail={
      <ToolRail
        countryConfig={countryConfig}
        accent={accent} onAccentChange={setAccent}
        accentLabel={accentLabel}
        voiceSlots={[{ key: "a", label: "Selected Voice", value: voiceName, onClick: () => setShowVoicePicker(true) }]}
        resultUrl={audioUrl} resultReady={!!audioUrl}
        downloadName="accentuate_converted" active={active}
        wordCount={transcriptWordCount}
      />
    }>
      {loading ? (
        <div style={{ flexGrow: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 18, textAlign: "center" }}>
          <ProcessingWave />
          <div style={{ fontSize: 18, fontWeight: 800, color: C.text }}>{progress || "Converting your audio…"}</div>
          <div style={{ fontSize: 13.5, color: C.muted, maxWidth: 340 }}>Transcribing your audio and converting it to your voice</div>
        </div>
      ) : (
        <div style={{ flexGrow: 1, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ width: "100%", maxWidth: 700 }}>
            <UploadZone variant="dashed" label="Click to upload or drag and drop" sub="WAV · MP3 · M4A" onFile={setFile} file={file} />
          </div>
        </div>
      )}

      <ErrorBox msg={error} />

      <ToolFooter
        meta=""
        actionLabel={audioUrl ? "Convert Again" : "Convert Audio"}
        onAction={convert}
        disabled={!file || loading}
      />

      {showVoicePicker && (
        <VoicePickerModal
          userEmail={userEmail}
          onClose={() => setShowVoicePicker(false)}
          onSelect={(sample, name) => { onChangeVoice && onChangeVoice(sample, name); setShowVoicePicker(false); }}
        />
      )}
    </ToolLayout>
  );
}

// ─ Screen: ADR / Voice swap ─────────────────────────────────────────────
function ADRRecord({ voiceSample, voiceName, country, durationLimit, onBack, onUseAnother, onStartOver, active = true, requireLessonLog = false, userEmail, onChangeVoice }) {
  const [showVoicePicker, setShowVoicePicker] = useState(false);
  const [tab, setTab] = useState("upload");   // matches the design: Upload Audio is the default
  const [blob, setBlob] = useState(null);
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [outputUrl, setOutputUrl] = useState(null);
  const [error, setError] = useState(null);

  const source = tab === "record" ? blob : file;

  const process = async () => {
    if (!source) return;
    setLoading(true); setError(null);
    try {
      // Check duration limit on uploaded files
      if (durationLimit && tab === "upload" && file) {
        const duration = await getAudioDuration(file);
        if (duration > durationLimit) {
          const mins = Math.floor(durationLimit / 60);
          throw new Error(`This file is ${Math.floor(duration / 60)}m ${Math.floor(duration % 60)}s, which exceeds your ${mins} minute limit. Try a shorter file.`);
        }
      }
      const finalBlob = await withClonedVoice(voiceSample, vId => voiceChangerFromBlob(source, vId));
      setOutputUrl(URL.createObjectURL(finalBlob));
      // ADR has no script text to count characters from — log the source
      // audio's duration (seconds) instead, so usage is still measurable.
      const durationSeconds = await getAudioDuration(source).catch(() => 0);
      logUsageEntry({ email: userEmail, mode: "Voice Swap/ADR", characters: 0, seconds: Math.round(durationSeconds) });
    } catch (e) { setError(e.message || "Processing failed. Please try again."); }
    finally { setLoading(false); }
  };

  const countryConfig = COUNTRIES[country];
  const accentLabel = countryConfig.label.replace(" Accent", "");
  const [accent, setAccent] = useState(DEFAULT_ACCENT);
  return (
    <ToolLayout rail={
      <ToolRail
        countryConfig={countryConfig}
        accent={accent} onAccentChange={setAccent}
        accentLabel={accentLabel}
        voiceSlots={[{ key: "a", label: "Selected Voice", value: voiceName, onClick: () => setShowVoicePicker(true) }]}
        resultUrl={outputUrl} resultReady={!!outputUrl}
        downloadName="accentuate_voiceswap" active={active}
      />
    }>
      {loading ? (
        <div style={{ flexGrow: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 18, textAlign: "center" }}>
          <ProcessingWave />
          <div style={{ fontSize: 18, fontWeight: 800, color: C.text }}>Applying your voice…</div>
          <div style={{ fontSize: 13.5, color: C.muted, maxWidth: 340 }}>Your recording is being converted into your cloned voice</div>
        </div>
      ) : (
        <div style={{ flexGrow: 1, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ width: "100%", maxWidth: 700 }}>
            <PillTabs
              active={tab}
              onChange={t => { setTab(t); setBlob(null); setFile(null); }}
              options={[
                { id: "upload", label: "Upload Audio", icon: <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M8 11V3M8 3L4.5 6.5M8 3l3.5 3.5M3 13h10" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg> },
                { id: "record", label: "Record", icon: <svg width="14" height="14" viewBox="0 0 16 16" fill="none"><rect x="5.5" y="1.5" width="5" height="9" rx="2.5" stroke="currentColor" strokeWidth="1.5"/><path d="M3 7.5a5 5 0 0 0 10 0M8 12.5V14.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg> },
              ]}
            />
            <div style={{ marginTop: 26 }}>
              {tab === "upload" && <UploadZone variant="dashed" label="Click to upload or drag and drop" sub="WAV · MP3 · M4A" onFile={setFile} file={file} />}
              {tab === "record" && <VoiceRecorder variant="dashed" onBlob={setBlob} maxDuration={durationLimit} />}
            </div>
            {tab === "record" && (
              <p style={{ margin: "14px 0 0", fontSize: 13.5, color: C.sub }}>
                <strong style={{ color: C.text }}>For best results:</strong> record in a quiet room, speak naturally for at least 30 seconds, and avoid background music or noise.
              </p>
            )}
          </div>
        </div>
      )}

      <ErrorBox msg={error} />

      <ToolFooter
        meta=""
        actionLabel={outputUrl ? "Convert Again" : "Convert Audio"}
        onAction={process}
        disabled={!source || loading}
      />

      {showVoicePicker && (
        <VoicePickerModal
          userEmail={userEmail}
          onClose={() => setShowVoicePicker(false)}
          onSelect={(sample, name) => { onChangeVoice && onChangeVoice(sample, name); setShowVoicePicker(false); }}
        />
      )}
    </ToolLayout>
  );
}

// ─ Podcast script parser ──────────────────────────────────────────────────
// Expects lines like "SPEAKER_NAME: dialogue text here"
// Continuation lines (without a colon label) are appended to the previous speaker.
// ─ PDF script extraction ────────────────────────────────────────────────
// Reconstructs line breaks from each text run's vertical position — PDF text
// content has no inherent line structure, so without this, speaker turns
// on separate lines can run together into one paragraph.
async function extractPdfText(file) {
  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
  let fullText = "";

  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    let lastY = null;
    let line = "";

    for (const item of content.items) {
      const y = item.transform[5];
      if (lastY !== null && Math.abs(y - lastY) > 2) {
        if (line.trim()) fullText += line.trim() + "\n";
        line = "";
      }
      line += item.str + " ";
      lastY = y;
    }
    if (line.trim()) fullText += line.trim() + "\n";
  }

  return fullText.trim();
}

function parsePodcastScript(text) {
  const lines = text.split("\n");
  const segments = [];
  let currentSpeaker = null;
  let currentText = "";

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const match = trimmed.match(/^([A-Za-z0-9\s._-]+?):\s*(.+)/);
    if (match) {
      if (currentSpeaker && currentText.trim()) {
        segments.push({ speaker: currentSpeaker.toUpperCase(), text: currentText.trim() });
      }
      currentSpeaker = match[1].trim();
      currentText = match[2];
    } else if (currentSpeaker) {
      currentText += " " + trimmed;
    }
  }
  if (currentSpeaker && currentText.trim()) {
    segments.push({ speaker: currentSpeaker.toUpperCase(), text: currentText.trim() });
  }
  return segments;
}

// Extract unique speaker names from a parsed script
function getUniqueSpeakers(segments) {
  const seen = new Set();
  return segments.map(s => s.speaker).filter(s => { if (seen.has(s)) return false; seen.add(s); return true; });
}

// ─ Screen: Create a podcast (two-voice conversation) ──────────────────────
const VOICE_LABELS = ["A", "B", "C", "D"];
const MAX_SPEAKERS = 4;

// One additional voice slot (Voice B, C, or D) — upload/record, confirm-clone,
// same lifecycle as the main setup's voice capture, just reusable per-slot.
function VoiceSlotEditor({ voice, onUpdate, onRemove, removable }) {
  const [library, setLibrary] = useState(null);
  const [libraryLoading, setLibraryLoading] = useState(false);

  const loadLibrary = async () => {
    setLibraryLoading(true);
    const rows = await fetchVoiceLibrary();
    setLibrary(rows);
    setLibraryLoading(false);
  };

  const setupVoice = async () => {
    onUpdate({ loading: true, error: null });
    try {
      let audioFile;
      if (voice.tab === "upload") {
        audioFile = voice.file;
      } else {
        const ext = voice.blob.type.includes("mp4") ? "mp4" : "webm";
        audioFile = new File([voice.blob], `voice_${voice.label.toLowerCase()}.${ext}`, { type: voice.blob.type || "audio/webm" });
      }
      const checkId = await cloneVoice(audioFile, `accentuate_check_${voice.label.toLowerCase()}_${Date.now()}`);
      await deleteVoice(checkId).catch(() => {});
      onUpdate({
        ready: true, loading: false, resolvedFile: audioFile,
        name: voice.tab === "upload" ? voice.file.name.replace(/\.[^/.]+$/, "") : `Speaker ${voice.label} recording`,
      });
    } catch (e) {
      onUpdate({ loading: false, error: e.message || `Voice ${voice.label} setup failed. Check your audio sample.` });
    }
  };

  // Picking a library voice skips cloning entirely — resolvedFile becomes
  // the voice's real ElevenLabs ID (a string), same pattern used everywhere
  // else in the app to distinguish "already a voice" from "needs cloning".
  const selectLibraryVoice = (v) => {
    onUpdate({ ready: true, loading: false, resolvedFile: v["Voice ID"], name: v.Name });
  };

  const hasFile = voice.tab === "upload" ? !!voice.file : !!voice.blob;

  return (
    <div style={{ marginBottom: 20 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 9 }}>
        <div style={{ fontSize: 11.5, fontWeight: 700, letterSpacing: "0.12em", color: "#7c837d", textTransform: "uppercase" }}>Voice {voice.label}</div>
        {removable && !voice.ready && (
          <button onClick={onRemove} style={{ background: "none", border: "none", color: C.muted2, fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: C.font }}>Remove</button>
        )}
      </div>

      {!voice.ready ? (
        <div style={{ background: "rgba(255,255,255,.4)", border: "1px solid rgba(255,255,255,.6)", borderRadius: 16, padding: 16 }}>
          <SegToggle
            active={voice.tab}
            onChange={t => {
              onUpdate({ tab: t, file: null, blob: null });
              if (t === "library" && library === null) loadLibrary();
            }}
            options={[
              { id: "upload", label: "Upload", icon: <svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M8 11V3M8 3L4.5 6.5M8 3l3.5 3.5M3 13h10" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" /></svg> },
              { id: "record", label: "Record", icon: <svg width="12" height="12" viewBox="0 0 16 16" fill="none"><rect x="5.5" y="1.5" width="5" height="9" rx="2.5" stroke="currentColor" strokeWidth="1.5" /><path d="M3 7.5a5 5 0 0 0 10 0M8 12.5V14.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /></svg> },
              { id: "library", label: "Library", icon: <svg width="13" height="13" viewBox="0 0 16 16" fill="none"><rect x="2" y="3" width="12" height="10" rx="2" stroke="currentColor" strokeWidth="1.5" /><path d="M5 6.5h6M5 9.5h4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /></svg> },
            ]}
          />
          {voice.tab === "upload" && (
            <UploadZone glass label={`Drop voice ${voice.label} sample`} sub="WAV · MP3 · M4A — 1 to 2 minutes recommended" onFile={f => onUpdate({ file: f, error: null })} file={voice.file} />
          )}
          {voice.tab === "record" && (
            <VoiceRecorder glass onBlob={b => onUpdate({ blob: b })} />
          )}
          {voice.tab === "library" && (
            <div style={{ marginTop: 14 }}>
              {libraryLoading && (
                <div style={{ textAlign: "center", padding: "18px 0" }}>
                  <ProcessingWave height={34} />
                  <div style={{ fontSize: 12.5, color: C.muted, marginTop: 8 }}>Loading voice library...</div>
                </div>
              )}
              {!libraryLoading && library && library.length === 0 && (
                <div style={{ textAlign: "center", padding: "16px 0", fontSize: 13, color: C.muted }}>No saved voices yet.</div>
              )}
              {!libraryLoading && library && library.length > 0 && (
                <div style={{ display: "flex", flexDirection: "column", gap: 8, maxHeight: 220, overflowY: "auto" }}>
                  {library.map(v => (
                    <div key={v["Voice ID"]} style={{ display: "flex", alignItems: "center", gap: 8, border: "1px solid rgba(0,0,0,.1)", borderRadius: 12, background: "rgba(255,255,255,.6)" }}>
                      <VoicePreviewButton voiceId={v["Voice ID"]} size={30} />
                      <button onClick={() => selectLibraryVoice(v)} style={{
                        flex: 1, textAlign: "left", padding: "10px 12px 10px 0", border: "none", background: "none", cursor: "pointer",
                        font: `700 13.5px ${C.font}`, color: C.text,
                      }}>{v.Name}</button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
          {hasFile && voice.tab !== "library" && !voice.loading && (
            <button onClick={setupVoice} style={{
              width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
              marginTop: 14, padding: 12, border: "none", borderRadius: 999, font: `700 14px ${C.font}`,
              background: C.green, color: "#fff", cursor: "pointer", boxShadow: C.greenGlow,
            }}>Confirm voice {voice.label}</button>
          )}
          {voice.loading && (
            <div style={{ textAlign: "center", padding: "16px 0" }}>
              <ProcessingWave height={40} />
              <div style={{ fontSize: 13, color: C.muted, marginTop: 10 }}>Setting up voice {voice.label}...</div>
            </div>
          )}
          {voice.error && <div style={{ marginTop: 10, fontSize: 12, color: C.error }}>{voice.error}</div>}
        </div>
      ) : (
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <SampleReadyChip name={voice.name || `Speaker ${voice.label}`} />
          <button onClick={() => onUpdate({ ready: false, file: null, blob: null })} style={{
            background: "none", border: "none", color: C.muted2, fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: C.font, textDecoration: "underline",
          }}>Change</button>
        </div>
      )}
    </div>
  );
}

function PodcastCreate({ voiceSample, voiceName, country, charLimit, onBack, onUseAnother, onStartOver, active = true, userEmail, onChangeVoice }) {
  const [showVoicePicker, setShowVoicePicker] = useState(false);
  const [accent, setAccent] = useState(DEFAULT_ACCENT);
  const [script, setScript] = useState("");
  const [pdfLoading, setPdfLoading] = useState(false);
  const [extraVoices, setExtraVoices] = useState([
    { label: "B", tab: "upload", file: null, blob: null, ready: false, loading: false, name: null, resolvedFile: null, error: null },
  ]);
  const [assignment, setAssignment] = useState({}); // { SPEAKER_NAME: "A" | "B" | "C" | "D" }
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState("");
  const [audioUrl, setAudioUrl] = useState(null);
  const [error, setError] = useState(null);

  const countryConfig = COUNTRIES[country];
  const accentLabel = countryConfig ? countryConfig.label.replace(" Accent", "") : "";

  const updateVoice = (label, patch) => {
    setExtraVoices(prev => prev.map(v => v.label === label ? { ...v, ...patch } : v));
  };
  const addVoiceSlot = () => {
    const nextLabel = VOICE_LABELS[extraVoices.length + 1]; // +1 since "A" is always the main voice
    if (!nextLabel) return;
    setExtraVoices(prev => [...prev, { label: nextLabel, tab: "upload", file: null, blob: null, ready: false, loading: false, name: null, resolvedFile: null, error: null }]);
  };
  const removeVoiceSlot = (label) => {
    setExtraVoices(prev => prev.filter(v => v.label !== label));
    setAssignment(prev => {
      const next = { ...prev };
      Object.keys(next).forEach(k => { if (next[k] === label) delete next[k]; });
      return next;
    });
  };

  // Available voice labels — "A" (main setup voice) plus each confirmed/pending extra slot
  const availableLabels = ["A", ...extraVoices.map(v => v.label)];

  // Parse script and detect speakers
  const segments = parsePodcastScript(script);
  const speakers = getUniqueSpeakers(segments);
  const tooManySpeakers = speakers.length > MAX_SPEAKERS;
  const notEnoughVoices = !tooManySpeakers && speakers.length > availableLabels.length;

  // Auto-assign speakers (in order of first appearance) when none are assigned yet
  useEffect(() => {
    if (speakers.length > 0 && speakers.length <= availableLabels.length) {
      const allUnassigned = speakers.every(s => !assignment[s]);
      if (allUnassigned) {
        const next = {};
        speakers.forEach((s, i) => { next[s] = availableLabels[i]; });
        setAssignment(next);
      }
    }
  }, [speakers.join(","), availableLabels.join(",")]); // eslint-disable-line

  const handlePdfUpload = async (file) => {
    setPdfLoading(true); setError(null);
    try {
      const text = await extractPdfText(file);
      if (!text) throw new Error("Couldn't find any readable text in that PDF.");
      setScript(text);
    } catch (e) {
      setError(e.message || "Couldn't read that PDF. Try a different file, or paste the script directly.");
    }
    setPdfLoading(false);
  };

  // Check if ready to generate
  const allVoicesReady = extraVoices.every(v => v.ready);
  const allAssigned = speakers.length > 0 && speakers.every(s => assignment[s]);
  const canGenerate = allVoicesReady && script.trim() && segments.length > 0 && allAssigned && !tooManySpeakers && !notEnoughVoices;

  const totalChars = segments.reduce((sum, s) => sum + s.text.length, 0);
  const totalWords = segments.reduce((sum, s) => sum + (s.text.trim() ? s.text.trim().split(/\s+/).length : 0), 0);
  const overLimit = charLimit && totalChars > charLimit;

  const generate = async () => {
    if (!canGenerate) return;
    setLoading(true); setError(null); setAudioUrl(null); setProgress("");
    try {
      const anchorVoiceId = countryConfig.hasAccentToggle
        ? ANCHOR_VOICES[accent].id
        : countryConfig.anchorId;
      const isDirect = countryConfig.hasAccentToggle && anchorVoiceId === null;

      // Clone every voice in use — main setup voice (A) plus each confirmed extra.
      // A string resolvedFile/voiceSample means it's already a saved library
      // voice — use directly, no cloning, and never delete it afterward.
      const voiceMap = {};
      const libraryLabels = new Set();
      const isLibraryVoiceA = typeof voiceSample === "string";
      if (isLibraryVoiceA) {
        voiceMap.A = voiceSample;
        libraryLabels.add("A");
      } else {
        setProgress("Cloning voice A...");
        voiceMap.A = await cloneVoice(voiceSample, `podcast_a_${Date.now()}`);
      }
      for (const v of extraVoices) {
        if (typeof v.resolvedFile === "string") {
          voiceMap[v.label] = v.resolvedFile;
          libraryLabels.add(v.label);
        } else {
          setProgress(`Cloning voice ${v.label}...`);
          voiceMap[v.label] = await cloneVoice(v.resolvedFile, `podcast_${v.label.toLowerCase()}_${Date.now()}`);
        }
      }

      try {
        const resultSegments = [];

        for (let i = 0; i < segments.length; i++) {
          const seg = segments[i];
          const voiceId = voiceMap[assignment[seg.speaker]];
          setProgress(`${seg.speaker} — line ${i + 1} of ${segments.length}...`);

          // Chunk long speaker turns — one seed per turn keeps chunks within
          // this same turn consistent, without flattening the natural
          // variation between separate dialogue lines across the podcast.
          const chunks = chunkScript(normalizeTextForTTS(seg.text), 2000);
          const turnSeed = Math.floor(Math.random() * 4294967295);
          const turnBlobs = [];
          for (const chunk of chunks) {
            if (isDirect) {
              // Direct — this speaker's own voice generates the line
              // directly, no accent anchor or conversion step.
              turnBlobs.push(await generateChunkAudio(chunk, voiceId, 1.0, turnSeed));
            } else {
              const ttsBlob = await generateChunkAudio(chunk, anchorVoiceId, 1.0, turnSeed);
              const converted = await voiceChangerFromBlob(ttsBlob, voiceId);
              turnBlobs.push(converted);
            }
          }
          const turnBlob = turnBlobs.length > 1 ? await concatenateAudioBlobs(turnBlobs) : turnBlobs[0];

          // Gap after this turn (400ms between speakers, 200ms same speaker)
          const nextSeg = segments[i + 1];
          const gapAfter = nextSeg
            ? (nextSeg.speaker !== seg.speaker ? 0.4 : 0.2)
            : 0;

          resultSegments.push({ blob: turnBlob, gapAfter });
        }

        setProgress("Combining conversation...");
        const finalBlob = await concatenateWithGaps(resultSegments);
        setAudioUrl(URL.createObjectURL(finalBlob));
        setProgress("");
        logUsageEntry({ email: userEmail, mode: "Podcast", characters: totalChars });
      } finally {
        Object.entries(voiceMap).forEach(([label, id]) => {
          if (libraryLabels.has(label)) return; // library voice — never delete
          deleteVoice(id).catch(() => {});
        });
      }
    } catch (e) {
      setError(e.message || "Podcast generation failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const [pickerSlot, setPickerSlot] = useState(null); // "A" | label | null

  // Rail voice slots: Voice A is the setup voice; extras are the added slots.
  // Each is labelled with the speaker it's assigned to, when known.
  const speakerFor = (label) => {
    const hit = Object.entries(assignment).find(([, v]) => v === label);
    return hit ? ` (${hit[0].charAt(0) + hit[0].slice(1).toLowerCase()})` : "";
  };
  const railSlots = [
    { key: "A", label: `Voice A${speakerFor("A")}`, value: voiceName, onClick: () => setPickerSlot("A") },
    ...extraVoices.map(v => ({
      key: v.label,
      label: `Voice ${v.label}${speakerFor(v.label)}`,
      value: v.ready ? v.name : null,
      empty: !v.ready,
      onClick: () => setPickerSlot(v.label),
    })),
  ];

  const applyPick = (sample, name) => {
    if (pickerSlot === "A") { onChangeVoice && onChangeVoice(sample, name); }
    else { updateVoice(pickerSlot, { ready: true, loading: false, resolvedFile: sample, name, error: null }); }
    setPickerSlot(null);
  };

  return (
    <ToolLayout rail={
      <ToolRail
        countryConfig={countryConfig}
        accent={accent} onAccentChange={setAccent}
        accentLabel={countryConfig.label.replace(" Accent", "")}
        voiceSlots={railSlots}
        onAddVoice={addVoiceSlot} canAddVoice={extraVoices.length < 3}
        resultUrl={audioUrl} resultReady={!!audioUrl}
        downloadName="accentuate_podcast" active={active}
        wordCount={totalWords}
      />
    }>
      {loading ? (
        <div style={{ flexGrow: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 18, textAlign: "center" }}>
          <ProcessingWave />
          <div style={{ fontSize: 18, fontWeight: 800, color: C.text }}>{progress || "Generating podcast…"}</div>
          <div style={{ fontSize: 13.5, color: C.muted, maxWidth: 340 }}>Each speaker turn is generated and converted individually</div>
        </div>
      ) : (
        <>
          <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 10 }}>
            <label style={{ display: "flex", alignItems: "center", gap: 7, fontSize: 13.5, fontWeight: 600, color: C.green, cursor: "pointer" }}>
              <svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M8 11V3M8 3L4.5 6.5M8 3l3.5 3.5M3 13h10" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round"/></svg>
              {pdfLoading ? "Reading PDF..." : "Upload a PDF script"}
              <input type="file" accept="application/pdf,.pdf" style={{ display: "none" }} disabled={pdfLoading}
                onChange={e => e.target.files[0] && handlePdfUpload(e.target.files[0])} />
            </label>
          </div>
          <textarea
            value={script} onChange={e => setScript(e.target.value)}
            placeholder={"SARAH: Welcome back to the show. Today we're discussing ...\nDAVID: Thanks for having me. The first thing I noticed was ...\nSARAH: That's really interesting because ..."}
            style={{
              flexGrow: 1, minHeight: 280, width: "100%", boxSizing: "border-box", border: "none", outline: "none",
              resize: "none", padding: 0, fontSize: 19, lineHeight: 1.6, color: C.text, background: "transparent", fontFamily: C.font,
            }}
          />
          {tooManySpeakers && (
            <div style={{ marginTop: 10, fontSize: 13, color: C.error }}>
              {speakers.length} speakers detected — maximum is {MAX_SPEAKERS}. Each line should start with SPEAKER_NAME: followed by their dialogue.
            </div>
          )}
          {notEnoughVoices && (
            <div style={{ marginTop: 10, fontSize: 13, color: C.amber }}>
              {speakers.length} speakers detected but only {availableLabels.length} voice{availableLabels.length === 1 ? "" : "s"} set up — add {speakers.length - availableLabels.length} more in the panel on the right.
            </div>
          )}
          {overLimit && (
            <div style={{ marginTop: 10, fontSize: 13, color: C.error }}>
              Script exceeds your {charLimit.toLocaleString()} character limit.
            </div>
          )}
        </>
      )}

      <ErrorBox msg={error} />

      <ToolFooter
        meta={`${totalChars} Characters / ${totalWords} words / ${speakers.length} speakers`}
        actionLabel={audioUrl ? "Generate Again" : "Generate Podcast"}
        onAction={generate}
        disabled={!canGenerate || overLimit || loading}
      />

      {pickerSlot && (
        <VoicePickerModal
          userEmail={userEmail}
          onClose={() => setPickerSlot(null)}
          onSelect={applyPick}
        />
      )}
    </ToolLayout>
  );
}

// ─ Access tiers ────────────────────────────────────────────────────────────
// "full" = no limits, "limited" = charLimit + durationLimit applied
const ACCESS_TIERS = {
  full:    { charLimit: null, durationLimit: null },
  limited: { charLimit: 1000, durationLimit: 120 }, // 120 seconds = 2 minutes
};

// Add the Kenyan office emails here ("full" or "limited").
const GUEST_ACCESS = {
  "michaelordor@gmail.com":    "full",
  "michaelordor@ulesson.com":  "full",
  "builders@ulesson.group":    "full",
};

function getCharLimit(email) {
  const tier = GUEST_ACCESS[email];
  if (!tier) return 0;
  return ACCESS_TIERS[tier]?.charLimit || null;
}

function getDurationLimit(email) {
  const tier = GUEST_ACCESS[email];
  if (!tier) return 0;
  return ACCESS_TIERS[tier]?.durationLimit || null; // null = unlimited
}

// ─ Screen: Login ──────────────────────────────────────────────────────────
// Same access-list validation as the original AccessGate (GUEST_ACCESS
// lookup, case-insensitive/trimmed) — only the visual layer changed.
// ─ Design-system pieces for the new screens ─────────────────────────────

// Pill row used for Upload / Record / Voice Library switches.
function PillTabs({ active, onChange, options, center = true }) {
  return (
    <div style={{ display: "flex", gap: 18, justifyContent: center ? "center" : "flex-start", flexWrap: "wrap" }}>
      {options.map(o => {
        const on = active === o.id;
        return (
          <button key={o.id} onClick={() => onChange(o.id)} style={{
            display: "flex", alignItems: "center", gap: 10, padding: "13px 24px", borderRadius: 10,
            border: `1px solid ${on ? "transparent" : C.borderSolid}`,
            background: on ? C.green : C.white, color: on ? "var(--acc-onaccent)" : C.text,
            font: `500 16px ${C.font}`, cursor: "pointer", whiteSpace: "nowrap",
          }}>
            {o.label}{o.icon}
          </button>
        );
      })}
    </div>
  );
}

// Large dashed drop area shared by onboarding, the picker modal and the tools.
function DashedBox({ children, onClick, style, ...rest }) {
  // `rest` carries the drag-and-drop handlers (onDragOver/onDragLeave/onDrop).
  // Without spreading it, those props are dropped and dragging a file onto the
  // box does nothing.
  return (
    <div onClick={onClick} {...rest} style={{
      border: `1px dashed ${C.borderSolid}`, borderRadius: 14, background: "var(--acc-dropzone)",
      display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
      padding: 30, boxSizing: "border-box", cursor: onClick ? "pointer" : "default", ...style,
    }}>{children}</div>
  );
}

// The pill-shaped audio player (dotted track + circular transport).
// The track is scrubbable: click or drag anywhere on it to seek.
function PillPlayer({ url, size = "md", active = true }) {
  const ref = useRef(null);
  const trackRef = useRef(null);
  const [playing, setPlaying] = useState(false);
  const [cur, setCur] = useState(0);
  const [dur, setDur] = useState(0);
  const [scrubbing, setScrubbing] = useState(false);

  useEffect(() => {
    if (!url) { setCur(0); setDur(0); setPlaying(false); return; }
    const a = new Audio(url);
    ref.current = a;
    const onTime = () => setCur(a.currentTime);
    const onMeta = () => setDur(a.duration || 0);
    const onEnd = () => { setPlaying(false); setCur(0); };
    a.addEventListener("timeupdate", onTime);
    a.addEventListener("loadedmetadata", onMeta);
    a.addEventListener("ended", onEnd);
    return () => {
      a.pause();
      a.removeEventListener("timeupdate", onTime);
      a.removeEventListener("loadedmetadata", onMeta);
      a.removeEventListener("ended", onEnd);
    };
  }, [url]);

  useEffect(() => { if (!active && ref.current) { ref.current.pause(); setPlaying(false); } }, [active]);

  const toggle = () => {
    const a = ref.current; if (!a) return;
    if (playing) { a.pause(); setPlaying(false); }
    else { a.play().then(() => setPlaying(true)).catch(() => {}); }
  };

  // Map a pointer position on the track to a time and seek there.
  const seekFromEvent = (e) => {
    const a = ref.current, el = trackRef.current;
    if (!a || !el || !dur) return;
    const r = el.getBoundingClientRect();
    const x = (e.touches ? e.touches[0].clientX : e.clientX) - r.left;
    const pct = Math.max(0, Math.min(1, x / r.width));
    a.currentTime = pct * dur;
    setCur(a.currentTime);
  };

  useEffect(() => {
    if (!scrubbing) return;
    const move = (e) => seekFromEvent(e);
    const up = () => setScrubbing(false);
    window.addEventListener("mousemove", move);
    window.addEventListener("mouseup", up);
    window.addEventListener("touchmove", move);
    window.addEventListener("touchend", up);
    return () => {
      window.removeEventListener("mousemove", move);
      window.removeEventListener("mouseup", up);
      window.removeEventListener("touchmove", move);
      window.removeEventListener("touchend", up);
    };
  }, [scrubbing, dur]); // eslint-disable-line

  const pct = dur ? Math.min(100, (cur / dur) * 100) : 0;
  const dots = 26;
  const big = size === "lg";
  const btn = big ? 58 : 34;
  const disabled = !url;

  const onTrackDown = (e) => {
    if (disabled) return;
    e.preventDefault();
    setScrubbing(true);
    seekFromEvent(e);
  };

  const onTrackKey = (e) => {
    const a = ref.current; if (!a || !dur) return;
    if (e.key === "ArrowRight") { a.currentTime = Math.min(dur, a.currentTime + 5); setCur(a.currentTime); }
    if (e.key === "ArrowLeft")  { a.currentTime = Math.max(0, a.currentTime - 5); setCur(a.currentTime); }
  };

  return (
    <div style={{
      display: "flex", alignItems: "center", gap: big ? 0 : 12,
      background: big ? (disabled ? "var(--acc-dropzone)" : "var(--acc-player-bg)") : "transparent",
      borderRadius: 999, padding: big ? 8 : 0, opacity: disabled ? .55 : 1,
    }}>
      <button onClick={toggle} disabled={disabled} aria-label={playing ? "Pause" : "Play"} style={{
        width: btn, height: btn, borderRadius: "50%", flexShrink: 0, border: "none",
        cursor: disabled ? "default" : "pointer",
        background: big ? (disabled ? "#c9cbcd" : "rgba(255,255,255,.18)") : C.green,
        color: big ? "var(--acc-player-fg)" : "var(--acc-onaccent)",
        display: "flex", alignItems: "center", justifyContent: "center",
      }}>
        {playing
          ? <svg width={big?16:11} height={big?16:11} viewBox="0 0 16 16"><rect x="3" y="2.5" width="4" height="11" rx="1.2" fill="currentColor"/><rect x="9" y="2.5" width="4" height="11" rx="1.2" fill="currentColor"/></svg>
          : <svg width={big?17:12} height={big?17:12} viewBox="0 0 16 16"><path d="M5 3l8 5-8 5V3z" fill="currentColor"/></svg>}
      </button>

      <div
        ref={trackRef}
        onMouseDown={onTrackDown}
        onTouchStart={onTrackDown}
        onKeyDown={onTrackKey}
        role="slider"
        tabIndex={disabled ? -1 : 0}
        aria-label="Seek"
        aria-valuemin={0}
        aria-valuemax={Math.round(dur)}
        aria-valuenow={Math.round(cur)}
        style={{
          flexGrow: 1, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 14,
          background: big ? "transparent" : C.green, borderRadius: 999,
          padding: big ? "0 20px 0 16px" : "9px 14px", minWidth: big ? 0 : 180,
          cursor: disabled ? "default" : "pointer", userSelect: "none", outline: "none",
        }}
      >
        <span style={{ display: "flex", gap: 3, flexGrow: 1, overflow: "hidden", pointerEvents: "none" }}>
          {Array.from({ length: dots }).map((_, i) => {
            const filled = pct > 0 && (i / dots) * 100 <= pct;
            return (
              <span key={i} style={{
                width: 3, height: filled ? 5 : 3, borderRadius: 999, flexShrink: 0,
                background: filled
                  ? (big ? "var(--acc-player-fg)" : "#fff")
                  : (big ? "var(--acc-player-track)" : "rgba(255,255,255,.5)"),
                transition: "height .12s",
              }} />
            );
          })}
        </span>
        <span style={{
          fontSize: big ? 15 : 12.5, color: big ? "var(--acc-player-fg)" : "#fff",
          fontVariantNumeric: "tabular-nums", flexShrink: 0, pointerEvents: "none",
        }}>{formatTime(cur)}</span>
      </div>
    </div>
  );
}


// Filename + extension + download, pinned under the result player.
function DownloadBar({ url, defaultName, ext = "mp3", disabled }) {
  const [name, setName] = useState(defaultName);
  useEffect(() => { setName(defaultName); }, [defaultName]);
  const download = () => {
    if (!url) return;
    const a = document.createElement("a");
    a.href = url; a.download = `${(name || defaultName).trim()}.${ext}`;
    document.body.appendChild(a); a.click(); a.remove();
  };
  return (
    <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
      <div style={{
        flexGrow: 1, display: "flex", alignItems: "center", gap: 8, padding: "0 15px", height: 48, boxSizing: "border-box",
        border: `1px solid ${C.borderSolid}`, borderRadius: 10, background: C.white, opacity: disabled ? .55 : 1,
      }}>
        <input value={name} onChange={e => setName(e.target.value)} disabled={disabled} style={{
          flexGrow: 1, minWidth: 0, border: "none", outline: "none", background: "transparent",
          font: `500 16px ${C.font}`, color: C.text,
        }} />
        <span style={{ fontSize: 15, color: C.muted, flexShrink: 0 }}>.{ext}</span>
      </div>
      <button onClick={download} disabled={disabled} title="Download" style={{
        width: 48, height: 48, flexShrink: 0, borderRadius: 10, border: `1px solid ${C.borderSolid}`,
        background: C.white, color: C.text, cursor: disabled ? "not-allowed" : "pointer",
        display: "flex", alignItems: "center", justifyContent: "center", opacity: disabled ? .55 : 1,
      }}>
        <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M12 3v12M7 11l5 5 5-5M4 20h16"/></svg>
      </button>
    </div>
  );
}

// Speed control: slider plus preset pills. Appears once a result exists.
const SPEED_PRESETS = [0.75, 1, 1.25, 1.5, 2];
function SpeedControl({ value, onChange, wordCount = 0, duration = 0, onMatchWPM, wpmNote }) {
  // Pace is measured from the adjusted audio, so it tracks the slider live.
  const wpm = wordCount > 0 && duration > 0 ? Math.round(wordCount / (duration / 60)) : null;
  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between" }}>
        <span style={{ fontSize: 14.5, color: C.sub }}>Speed</span>
        <span style={{ fontSize: 17, color: C.text, fontVariantNumeric: "tabular-nums" }}>{value}×</span>
      </div>
      <input type="range" min="0.5" max="2" step="0.05" value={value}
        onChange={e => onChange(parseFloat(e.target.value))}
        style={{ width: "100%", margin: "12px 0 14px", accentColor: C.text }} />
      <div style={{ display: "flex", gap: 9, flexWrap: "wrap" }}>
        {SPEED_PRESETS.map(p => {
          const on = Math.abs(value - p) < 0.001;
          return (
            <button key={p} onClick={() => onChange(p)} style={{
              padding: "9px 17px", borderRadius: 999, cursor: "pointer", font: `500 14px ${C.font}`,
              border: `1px solid ${on ? "transparent" : C.borderSolid}`,
              background: on ? C.text : C.white, color: on ? C.page : C.text,
            }}>{p}×</button>
          );
        })}
      </div>
      {wordCount > 0 && onMatchWPM && (
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginTop: 14,
          padding: "10px 14px", borderRadius: 10, background: C.greenLight, border: `1px solid ${C.greenBorder}`,
        }}>
          <span style={{ fontSize: 12.5, color: C.sub2 }}>{wpm ? `${wpm} words per minute` : "Calculating pace..."}</span>
          <button onClick={onMatchWPM} style={{
            flexShrink: 0, padding: "8px 14px", borderRadius: 999, border: "none",
            background: C.green, color: "var(--acc-onaccent)", font: `700 12.5px ${C.font}`, cursor: "pointer",
          }}>Match 100 WPM</button>
        </div>
      )}
      {wpmNote && <div style={{ fontSize: 11.5, color: C.amber, marginTop: 8 }}>{wpmNote}</div>}
    </div>
  );
}


